import * as React from "react";
import { IoIosMenu } from "react-icons/io";
import useEssential from "../hooks/useEssential";
import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import {
  Drawer,
  DrawerContent,
  DrawerHeader,
  DrawerBody,
  DrawerFooter,
  Button,
  useDisclosure,
} from "@heroui/react";

function NavigationLinks() {
  const { links } = useEssential();

  return (
    <div className="flex flex-wrap gap-10 text-sm font-bold size leading-5 uppercase text-neutral-900 max-md:max-w-full minimumMenu:hidden">
      {Object.keys(links).map((key) => {
        return (
          <Link
            hidden={!links[key].activate}
            key={key}
            to={links[key].link}
            className="hover:text-cyan-600 focus:outline-none focus:ring-2 focus:ring-cyan-600 focus:ring-offset-2"
          >
            {links[key].text}
          </Link>
        );
      })}
    </div>
  );
}

function MenuButton({ onClick }) {
  return (
    <div
      id="menuButton"
      className="flex flex-col cursor-pointer"
      aria-hidden="true"
      onClick={onClick}
    >
      <IoIosMenu size="3rem" />
    </div>
  );
}

function Header() {
  const { links } = useEssential();
  const { isOpen, onOpen, onOpenChange } = useDisclosure();
  const [showHeader, setShowHeader] = useState(true);
  const [lastScrollY, setLastScrollY] = useState(0);

  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY < lastScrollY || window.scrollY === 0) {
        setShowHeader(true);
      } else {
        setShowHeader(false);
      }
      setLastScrollY(window.scrollY);
    };

    window.addEventListener("scroll", handleScroll);
    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, [lastScrollY]);

  return (
    <>
      <nav
        className={`fixed flex flex-wrap gap-5 justify-between px-20 minimumMenu:px-5 py-3 w-screen bg-white max-md:px-5 max-md:max-w-full items-center z-30 transition-transform duration-300 ${
          showHeader ? "translate-y-0" : "-translate-y-full"
        }`}
        role="navigation"
        aria-label="Main navigation"
      >
        <a href="/">
          <img
            loading="lazy"
            src="/images/logo.png"
            className="object-contain shrink-0 mt-2 max-w-full w-[155px]"
            alt=""
          />
        </a>

        <NavigationLinks />
        <MenuButton onClick={onOpen} />
      </nav>

      <div
        className={`${isOpen ? "" : "hidden"} fixed top-0 left-0 w-full h-full bg-black bg-opacity-50 z-[40] overflow-hidden`}
      ></div>

      <Drawer
        size="lg"
        isOpen={isOpen}
        motionProps={{
          variants: {
            enter: {
              opacity: 1,
              x: 0,
              duration: 6,
            },
            exit: {
              x: 100,
              opacity: 0,
              duration: 0.7,
            },
          },
        }}
        hideCloseButton
        onOpenChange={onOpenChange}
      >
        <DrawerContent>
          {(onClose) => (
            <>
              <DrawerBody>
                <div
                  className={`fixed top-0 right-0 z-50 pr-10 pt-14 h-full bg-white shadow-lg 
                  }`}
                >
                  <div className="p-8">
                    <div className="flex flex-col space-y-5 w-44">
                      {Object.keys(links).map((key, index) => {
                        return (
                          <Link
                            to={links[key].link}
                            key={key}
                            hidden={!links[key].activate}
                          >
                            <span
                              className={`block text-2xl font-bold transition-transform hover:translate-x-2 hover:underline duration-500
                                `}
                              onClick={onClose}
                            >
                              {links[key].text}
                            </span>
                          </Link>
                        );
                      })}
                    </div>
                  </div>
                </div>
              </DrawerBody>
            </>
          )}
        </DrawerContent>
      </Drawer>
    </>
  );
}

export default Header;
