import React, { useState, useRef, useCallback } from "react";
import ReactCrop, { centerCrop, makeAspectCrop } from "react-image-crop";
import "react-image-crop/dist/ReactCrop.css";
import {
  Modal,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  Checkbox,
  Input,
} from "@heroui/react";

export default function ImageResizeModal({
  isOpen,
  onClose,
  image,
  onImageChange,
}) {
  const [crop, setCrop] = useState(null);
  const [completedCrop, setCompletedCrop] = useState(null);
  const [aspect, setAspect] = useState(1);
  const [isAspectLocked, setIsAspectLocked] = useState(true);
  const imgRef = useRef(null);
  const canvasRef = useRef(null);

  const onImageLoad = (e) => {
    const { width, height } = e.currentTarget;
    setCrop(
      centerCrop(
        makeAspectCrop({ unit: "%", width: 50 }, aspect, width, height),
        width,
        height
      )
    );
  };

  const getCroppedImage = useCallback(() => {
    if (!completedCrop || !imgRef.current || !canvasRef.current) return;

    const image = imgRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");

    const scaleX = image.naturalWidth / image.width;
    const scaleY = image.naturalHeight / image.height;

    canvas.width = completedCrop.width * scaleX;
    canvas.height = completedCrop.height * scaleY;

    ctx.drawImage(
      image,
      completedCrop.x * scaleX,
      completedCrop.y * scaleY,
      completedCrop.width * scaleX,
      completedCrop.height * scaleY,
      0,
      0,
      canvas.width,
      canvas.height
    );

    canvas.toBlob((blob) => {
      if (!blob) return;
      const newImageUrl = URL.createObjectURL(blob);
      const newImageFile = new File([blob], "cropped.png", {
        type: "image/png",
      });
      onImageChange(newImageUrl, newImageFile);
      onClose();
    }, "image/png");
  }, [completedCrop, onImageChange, onClose]);

  return (
    <Modal
      isOpen={isOpen}
      onOpenChange={onClose}
      hideCloseButton
      backdrop="blur"
      classNames={{
        body: "py-6 p-4 bg-neutral-100",
        base: "relative pointer-events-auto flex border-gray-300 bg-white text-gray-800 max-w-[600px] shadow-lg",
        header: "border-b-[1px] border-gray-300 p-2 ",
        footer: "border-t-[1px] border-gray-300 p-2",
        closeButton: "hover:bg-gray-100 active:bg-gray-200",
        wrapper: "pointer-events-none overflow-auto z-50",
      }}
    >
      <ModalContent>
        <ModalHeader>이미지 편집</ModalHeader>
        <ModalBody>
          {image && (
            <div className="flex flex-col items-center">
              <div className="flex items-center mb-4">
                <h3>{"이미지 비율 조절\n(자유비율은 0)"}</h3>
                <input
                  className="p-2 ml-2 rounded-md border border-gray-300"
                  type="number"
                  value={aspect}
                  onChange={(e) => setAspect(Number(e.target.value))}
                  disabled={!isAspectLocked}
                />
              </div>
              <ReactCrop
                crop={crop}
                onChange={(newCrop) => setCrop(newCrop)}
                onComplete={(c) => setCompletedCrop(c)}
                aspect={isAspectLocked ? aspect : undefined}
              >
                <img
                  ref={imgRef}
                  src={image}
                  alt="Crop"
                  onLoad={onImageLoad}
                  className="max-w-full"
                  crossOrigin="anonymous"
                />
              </ReactCrop>
              <canvas ref={canvasRef} className="hidden" />
            </div>
          )}
        </ModalBody>
        <ModalFooter>
          <Button color="primary" onPress={getCroppedImage}>
            적용
          </Button>
          <Button onPress={onClose}>취소</Button>
        </ModalFooter>
      </ModalContent>
    </Modal>
  );
}
