// recoil

import { useRecoilState } from "recoil";
import {
  linksState,
  adminState,
  textInfosState,
} from "../atoms/essentialAtoms";

export default function useEssential() {
  const [links, setLinks] = useRecoilState(linksState);
  const [admin, setAdmin] = useRecoilState(adminState);
  const [textInfo, setTextInfo] = useRecoilState(textInfosState);

  return { links, setLinks, admin, setAdmin, textInfo, setTextInfo };
}
