import React, { useEffect, useState } from "react";
import {
  Modal,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  useDraggable,
  Input,
} from "@heroui/react";
import { BiImageAdd } from "react-icons/bi";
import useEssential from "../../hooks/useEssential";
import useCommit from "../../hooks/useCommit";
import { BsPersonFillAdd } from "react-icons/bs";
import { set } from "@recoiljs/recoil";
import ImageResizeModal from "../ImageResizeModal";

export default function PeopleSettingMenu({ isOpen, onOpen, onOpenChange }) {
  const { admin } = useEssential();
  const targetRef = React.useRef(null);
  const { moveProps } = useDraggable({ targetRef, isDisabled: !isOpen });
  const { updateFiles } = useCommit();
  const { textInfo, setTextInfo } = useEssential();
  const [peopleInfos, setPeopleInfos] = useState(textInfo.peopleInfos);
  const [isResizeModalOpen, setIsResizeModalOpen] = useState(false);

  useEffect(() => {
    setPeopleInfos(textInfo.peopleInfos);
    console.log(textInfo.peopleInfos);
  }, [textInfo.peopleInfos]);

  const getBase64FromImageFile = (file) => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result?.toString().split(",")[1]);
      reader.onerror = (error) => reject(error);
    });
  };

  const onSave = async () => {
    let textInfoTmp = JSON.parse(JSON.stringify({ ...textInfo, peopleInfos }));
    let ImageDatas = [];
    newImage.forEach(async (image) => {
      ImageDatas.push({
        path: `images/people/${image.name}_img.png`,
        content: await getBase64FromImageFile(image.file),
      });
    });
    setTextInfo((prev) => ({ ...prev, peopleInfos }));
    setNewImage([]);
    ImageDatas.push({
      action: "add",
      path: "datas/textInfos.json",
      content: JSON.stringify(textInfoTmp, null, 2),
    });

    console.log(ImageDatas);

    await updateFiles(
      ImageDatas,
      // {
      //   path: "datas/textInfos.json",
      //   content: JSON.stringify(textInfo, null, 2),
      // },
      "Update people infos"
    );
    alert("성공적으로 저장하였습니다. 적용에는 5분정도 소요됩니다.");
  };

  const handleInputChange = (category, position = "", index, field, value) => {
    setPeopleInfos((prev) =>
      position === ""
        ? {
            ...prev,
            [category]: prev[category].map((person, i) =>
              i === index ? { ...person, [field]: value } : person
            ),
          }
        : {
            ...prev,
            [category]: {
              ...prev[category],
              [position]: prev[category][position].map((person, i) =>
                i === index ? { ...person, [field]: value } : person
              ),
            },
          }
    );
  };

  const handleDetailChange = (field, value) => {
    setSelectedPeople((prev) => ({
      ...prev,
      person: { ...prev.person, [field]: value },
    }));
  };

  const [isDragging, setIsDragging] = useState(false);

  // 파일 선택 이벤트 핸들러
  const handleFileChange = (event) => {
    const file = event.target.files?.[0];
    if (file) {
      updateImage(file);
    }
  };

  // 드래그 앤 드롭 관련 이벤트 핸들러
  const handleDragOver = (event) => {
    event.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const [positionData, setPositionData] = useState({
    category: "",
    position: "",
  });

  const [newImage, setNewImage] = useState([]);

  const handleDrop = (event) => {
    event.preventDefault();
    setIsDragging(false);
    const file = event.dataTransfer.files?.[0];

    if (file) {
      updateImage(file);
    }
  };

  // 이미지 업데이트
  const updateImage = (file) => {
    const reader = new FileReader();
    reader.onload = () => {
      setNewImage((prev) => [
        ...prev.filter((image) => image.name !== selectedPeople.person.name),
        {
          imageLink: reader.result,
          file: file,
          name: selectedPeople.person.name,
        },
      ]);
      setSelectedPeople((prev) => ({
        ...prev,
        person: {
          ...prev.person,
          imageSrc: `images/people/${prev.person.name}_img.png`,
        },
      }));
    };
    reader.readAsDataURL(file);
  };
  const [selectedPeople, setSelectedPeople] = useState(null);

  useEffect(() => {
    if (selectedPeople !== null) {
      console.log(selectedPeople);
    }
  }, [selectedPeople]);

  return (
    <>
      <Modal
        isDismissable={false}
        isKeyboardDismissDisabled={true}
        ref={targetRef}
        isOpen={isOpen}
        onOpenChange={onOpenChange}
        backdrop="transparent"
        hideCloseButton
        classNames={{
          body: "py-6 p-4 bg-neutral-100",
          base: `relative pointer-events-auto flex border-gray-300 bg-white text-gray-800 ${
            selectedPeople == null ? "max-w-[800px]" : "max-w-[600px]"
          } shadow-lg`,
          header: "border-b-[1px] border-gray-300 p-2 ",
          footer: "border-t-[1px] border-gray-300 p-2",
          closeButton: "hover:bg-gray-100 active:bg-gray-200",
          wrapper: "pointer-events-none overflow-auto z-50",
        }}
      >
        <ModalContent>
          {(onClose) => (
            <>
              <ModalHeader {...moveProps} className="flex flex-col gap-1">
                Peoples
              </ModalHeader>
              <ModalBody>
                <div className="relative w-full">
                  <div className="flex flex-row flex-wrap gap-4 max-h-[70vh] overflow-auto">
                    {selectedPeople === null ? (
                      Object.keys(peopleInfos).map((category) => (
                        <React.Fragment key={category}>
                          <div className="w-full border-b-2 border-gray-300 my-4">
                            <h2 className="text-xl font-semibold">
                              {category === "alumni"
                                ? "Alumni"
                                : "Current Members"}
                            </h2>
                          </div>
                          {category === "alumni"
                            ? peopleInfos[category].map((person, index) => (
                                <div
                                  key={index}
                                  className="flex flex-col gap-2 items-center p-2 shadow-md bg-white rounded-md hover:shadow-lg hover:translate-y-[-4px] hover:brightness-105 transition-all"
                                  onClick={() => {
                                    setSelectedPeople({
                                      person,
                                    });
                                    setPositionData({
                                      category,
                                      position: "",
                                    });
                                    setPeopleInfos((prev) => ({
                                      ...prev,
                                      [category]: prev[category].filter(
                                        (person, i) => i !== index
                                      ),
                                    }));
                                  }}
                                >
                                  <div className="w-40 flex-1">
                                    {person.imageSrc === "null" ? (
                                      <div className="w-full h-full rounded-md bg-neutral-100 flex items-center justify-center">
                                        <BiImageAdd size={"80px"} />
                                      </div>
                                    ) : newImage.find(
                                        (image) => image.name === person.name
                                      ) ? (
                                      <img
                                        src={
                                          newImage.find(
                                            (image) =>
                                              image.name === person.name
                                          ).imageLink
                                        }
                                        alt={person.name}
                                        className="object-cover w-full h-full rounded-md"
                                      />
                                    ) : (
                                      <img
                                        src={person.imageSrc}
                                        alt={person.name}
                                        className="object-cover w-full h-full rounded-md"
                                      />
                                    )}
                                  </div>
                                  <div className="w-40 flex-0">
                                    <Input
                                      classNames={{
                                        input: "text-lg font-bold text-center",
                                      }}
                                      value={person.name}
                                      onChange={(e) =>
                                        handleInputChange(
                                          category,
                                          index,
                                          "name",
                                          e.target.value
                                        )
                                      }
                                    />
                                    <Input
                                      classNames={{
                                        input:
                                          "text-md font-normal text-center",
                                      }}
                                      value={person.title}
                                      onChange={(e) =>
                                        handleInputChange(
                                          category,
                                          index,
                                          "title",
                                          e.target.value
                                        )
                                      }
                                    />
                                  </div>
                                </div>
                              ))
                            : Object.keys(peopleInfos[category]).map(
                                (position) =>
                                  peopleInfos[category][position].map(
                                    (person, index) => (
                                      <div
                                        key={index}
                                        onClick={() => {
                                          setSelectedPeople({
                                            person,
                                          });
                                          setPositionData({
                                            category,
                                            position,
                                          });
                                          setPeopleInfos((prev) => ({
                                            ...prev,
                                            [category]: {
                                              ...prev[category],
                                              [position]: prev[category][
                                                position
                                              ].filter(
                                                (person, i) => i !== index
                                              ),
                                            },
                                          }));
                                        }}
                                        className="flex flex-col gap-2 items-center p-2 shadow-md bg-white rounded-md hover:shadow-lg hover:translate-y-[-4px] hover:brightness-105 transition-all relative group"
                                      >
                                        <div className="w-40 flex-1">
                                          {person.imageSrc === "null" ? (
                                            <div className="w-full h-full rounded-md bg-neutral-100 flex items-center justify-center">
                                              <BiImageAdd size={"80px"} />
                                            </div>
                                          ) : newImage.find(
                                              (image) =>
                                                image.name === person.name
                                            ) ? (
                                            <img
                                              src={
                                                newImage.find(
                                                  (image) =>
                                                    image.name === person.name
                                                ).imageLink
                                              }
                                              alt={person.name}
                                              className="object-cover w-full h-full rounded-md"
                                            />
                                          ) : (
                                            <img
                                              src={person.imageSrc}
                                              alt={person.name}
                                              className="object-cover w-full h-full rounded-md"
                                            />
                                          )}
                                        </div>
                                        <div className="w-40 flex-0">
                                          <Input
                                            classNames={{
                                              input:
                                                "text-lg font-bold text-center",
                                            }}
                                            value={person.name}
                                            onChange={(e) =>
                                              handleInputChange(
                                                category,
                                                index,
                                                "name",
                                                e.target.value
                                              )
                                            }
                                          />

                                          <Input
                                            classNames={{
                                              input:
                                                "text-md font-normal text-center",
                                            }}
                                            value={person.title}
                                            onChange={(e) =>
                                              handleInputChange(
                                                category,
                                                index,
                                                "title",
                                                e.target.value
                                              )
                                            }
                                          />
                                          <p
                                            className="
                                        text-md font-normal text-center
                                        "
                                          >
                                            {position.charAt(0).toUpperCase() +
                                              position.slice(1)}
                                          </p>
                                        </div>
                                      </div>
                                    )
                                  )
                              )}
                          <div className="flex flex-col gap-4 items-center p-2 shadow-md bg-white rounded-md hover:shadow-lg hover:translate-y-[-4px] hover:brightness-105 transition-all">
                            <div className="w-40 aspect-square">
                              <div className="w-full h-full rounded-md bg-neutral-100 flex items-center justify-center">
                                <BsPersonFillAdd size={"80px"} />
                              </div>
                            </div>
                            <div className="w-40">
                              <Input
                                classNames={{
                                  input: "text-lg font-bold text-center",
                                }}
                                value="New people"
                                disabled
                              />
                              <h3 className="text-gray-500 font-normal text-center text-wrap break-words">
                                New people
                              </h3>
                            </div>
                          </div>
                        </React.Fragment>
                      ))
                    ) : (
                      <div className="flex flex-row gap-4 w-full">
                        <div className="flex flex-col items-center">
                          <label
                            className={`w-40 relative cursor-pointer ${
                              isDragging ? "border-2 border-blue-500" : ""
                            }`}
                            onDragOver={handleDragOver}
                            onDragLeave={handleDragLeave}
                            onDrop={handleDrop}
                          >
                            <input
                              type="file"
                              className="hidden"
                              onChange={handleFileChange}
                            />
                            {isDragging ? (
                              <div className="w-full h-full rounded-md aspect-[0.812] bg-gray-200 flex items-center justify-center">
                                <p className="text-gray-600">
                                  파일을 올려 불러오기
                                </p>
                              </div>
                            ) : selectedPeople.person.imageSrc === "null" ? (
                              <div className="w-full h-full rounded-md bg-neutral-100 flex items-center justify-center">
                                <BiImageAdd size={"80px"} />
                              </div>
                            ) : newImage.find(
                                (image) =>
                                  image.name === selectedPeople.person.name
                              ) ? (
                              <img
                                src={
                                  newImage.find(
                                    (image) =>
                                      image.name === selectedPeople.person.name
                                  ).imageLink
                                }
                                alt={selectedPeople.person.name}
                                className="object-cover w-full h-full rounded-md"
                              />
                            ) : (
                              <img
                                src={selectedPeople.person.imageSrc}
                                alt={selectedPeople.person.name}
                                className="object-cover w-full h-full rounded-md"
                              />
                            )}
                          </label>
                          <Button
                            variant="light"
                            className="mt-2 bg-neutral-300 w-full rounded-md"
                            onPress={() => {
                              setNewImage((prev) =>
                                prev.filter(
                                  (image) =>
                                    image.name !== selectedPeople.person.name
                                )
                              );
                              setSelectedPeople((prev) => ({
                                ...prev,
                                person: {
                                  ...prev.person,
                                  imageSrc: "null",
                                },
                              }));
                            }}
                          >
                            Reset
                          </Button>
                          <Button
                            variant="light"
                            className="mt-2 bg-neutral-300 w-full rounded-md"
                            onPress={() => setIsResizeModalOpen(true)}
                          >
                            Edit
                          </Button>
                        </div>
                        <div className="flex flex-col gap-3 flex-1">
                          <div className="flex flex-row gap-2">
                            <h3 className=" text-nowrap ">이름: </h3>
                            <Input
                              defaultValue={selectedPeople.person.name}
                              onChange={(e) =>
                                handleDetailChange("name", e.target.value)
                              }
                            />
                          </div>
                          <div className="flex flex-row gap-2">
                            <h3 className=" text-nowrap">직책: </h3>
                            <Input
                              defaultValue={selectedPeople.person.title}
                              onChange={(e) =>
                                handleDetailChange("title", e.target.value)
                              }
                            />
                          </div>

                          <div className="flex flex-row gap-2">
                            <h3 className=" text-nowrap">설명: </h3>
                            <Input
                              defaultValue={selectedPeople.person.description}
                              onChange={(e) =>
                                handleDetailChange(
                                  "description",
                                  e.target.value
                                )
                              }
                            />
                          </div>
                          <div className="flex flex-row gap-2">
                            <h3 className=" text-nowrap">이메일: </h3>
                            <Input
                              defaultValue={selectedPeople.person.email}
                              onChange={(e) =>
                                handleDetailChange("email", e.target.value)
                              }
                            />
                          </div>
                          <div className="flex flex-row gap-2">
                            <h3 className=" text-nowrap">CV 링크: </h3>
                            <Input
                              defaultValue={selectedPeople.person.cvLink}
                              onChange={(e) =>
                                handleDetailChange("cvLink", e.target.value)
                              }
                            />
                          </div>
                          <div className="flex flex-row gap-2">
                            <div className="flex flex-col gap-2">
                              <h3>상태</h3>
                              <select
                                value={positionData.category}
                                onChange={(e) =>
                                  setPositionData({
                                    category: e.target.value,
                                    position:
                                      e.target.value === "alumni"
                                        ? ""
                                        : "professor",
                                  })
                                }
                              >
                                <option value="currentMember">Member</option>
                                <option value="alumni">Alumni</option>
                              </select>
                            </div>
                            <div className="flex flex-col gap-2">
                              <h3>포지션</h3>
                              <select
                                value={positionData.position}
                                disabled={positionData.category === "alumni"}
                                onChange={(e) =>
                                  setPositionData({
                                    ...positionData,
                                    position: e.target.value,
                                  })
                                }
                              >
                                {selectedPeople.category === "alumni" ? (
                                  <option value=""></option>
                                ) : (
                                  <>
                                    <option value="professor">Professor</option>
                                    <option value="member">Member</option>
                                    <option value="student">Student</option>
                                    <option value="" hidden>
                                      NULL
                                    </option>
                                  </>
                                )}
                              </select>
                            </div>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              </ModalBody>
              <ModalFooter>
                <Button
                  color="primary"
                  onPress={onSave}
                  className={`${selectedPeople != null ? "hidden" : ""}`}
                >
                  Save
                </Button>
                <Button
                  color="danger"
                  variant="light"
                  className={`${selectedPeople == null ? "hidden" : ""}`}
                  onPress={() => {
                    if (positionData.category === "alumni") {
                      setPeopleInfos((prev) => ({
                        ...prev,
                        alumni: [...prev.alumni, selectedPeople.person],
                      }));
                    } else {
                      setPeopleInfos((prev) => ({
                        ...prev,
                        currentMember: {
                          ...prev.currentMember,
                          [positionData.position]: [
                            ...prev.currentMember[positionData.position],
                            selectedPeople.person,
                          ],
                        },
                      }));
                    }
                    setSelectedPeople(null);
                    setPositionData({ category: "", position: "" });
                  }}
                >
                  Apply
                </Button>

                <Button
                  color="danger"
                  variant="light"
                  className={`${selectedPeople != null ? "hidden" : ""}`}
                  onPress={() => {
                    setPeopleInfos(textInfo.peopleInfos);
                    setSelectedPeople(null);
                    setNewImage([]);
                  }}
                >
                  Reset
                </Button>

                <Button
                  color="danger"
                  variant="light"
                  onPress={() => {
                    onClose();
                    setSelectedPeople(null);
                  }}
                >
                  Close
                </Button>
              </ModalFooter>
            </>
          )}
        </ModalContent>
      </Modal>
      <ImageResizeModal
        isOpen={isResizeModalOpen}
        onClose={() => setIsResizeModalOpen(false)}
        image={selectedPeople?.person?.imageSrc}
        onImageChange={(image, file) => {
          setNewImage((prev) => [
            ...prev.filter(
              (image) => image.name !== selectedPeople.person.name
            ),
            {
              imageLink: image,
              file: file,
              name: selectedPeople.person.name,
            },
          ]);
        }}
      />
    </>
  );
}
