import React, { useState, useEffect, useRef } from "react";
import { motion } from "framer-motion";
import useEssential from "../hooks/useEssential";
import { IoSettings } from "react-icons/io5";
import { Link } from "react-router-dom";
import {
  Modal,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  useDraggable,
  Input,
} from "@heroui/react";
import useCommit from "../hooks/useCommit";
import { useDisclosure } from "@heroui/react";

const HeroEditMenu = ({ isOpen, onOpenChange }) => {
  const { textInfo, setTextInfo } = useEssential();
  const { updateFiles } = useCommit();
  const targetRef = useRef(null);
  const { moveProps } = useDraggable({ targetRef, isDisabled: !isOpen });
  const [heroTitle, setHeroTitle] = useState(textInfo.landingInfos.HeroTitle);
  const [heroSubtitle, setHeroSubtitle] = useState(
    textInfo.landingInfos.HeroSubtitle
  );

  useEffect(() => {
    setHeroTitle(textInfo.landingInfos.HeroTitle);
    setHeroSubtitle(textInfo.landingInfos.HeroSubtitle);
  }, [textInfo]);

  const onSave = async () => {
    let updatedTextInfo = {
      ...textInfo,
      landingInfos: {
        ...textInfo.landingInfos,
        HeroTitle: heroTitle,
        HeroSubtitle: heroSubtitle,
      },
    };
    await updateFiles(
      [
        {
          action: "add",
          path: "datas/textInfos.json",
          content: JSON.stringify(updatedTextInfo, null, 2),
        },
      ],
      "Update Hero infos"
    );
    setTextInfo(updatedTextInfo);
    alert("성공적으로 저장하였습니다. 적용에는 5분정도 소요됩니다.");
  };

  return (
    <Modal
      isDismissable={false}
      isKeyboardDismissDisabled={true}
      ref={targetRef}
      isOpen={isOpen}
      onOpenChange={onOpenChange}
      backdrop="transparent"
      hideCloseButton
      classNames={{
        body: "py-6 p-4 bg-neutral-100",
        base: "relative pointer-events-auto flex border-gray-300 bg-white text-gray-800 max-w-[600px] shadow-lg",
        header: "border-b-[1px] border-gray-300 p-2 ",
        footer: "border-t-[1px] border-gray-300 p-2",
        closeButton: "hover:bg-gray-100 active:bg-gray-200",
        wrapper: "pointer-events-none overflow-auto z-50",
      }}
    >
      <ModalContent>
        {(onClose) => (
          <>
            <ModalHeader {...moveProps} className="flex flex-col gap-1">
              <div className="flex justify-between">
                <h2 className="text-lg font-semibold">Edit Hero</h2>
              </div>
            </ModalHeader>
            <ModalBody>
              <div className="flex flex-col gap-2">
                <label className="block text-sm font-medium text-gray-700">
                  Title:
                </label>
                <Input
                  className="bg-neutral-100 p-2 py-1 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  value={heroTitle}
                  onChange={(e) => setHeroTitle(e.target.value)}
                />
                <label className="block text-sm font-medium text-gray-700">
                  Subtitle:
                </label>
                <Input
                  className="bg-neutral-100 p-2 py-1 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  value={heroSubtitle}
                  onChange={(e) => setHeroSubtitle(e.target.value)}
                />
              </div>
            </ModalBody>
            <ModalFooter>
              <Button color="primary" onPress={onSave}>
                Save
              </Button>
              <Button color="danger" variant="light" onPress={onClose}>
                Close
              </Button>
            </ModalFooter>
          </>
        )}
      </ModalContent>
    </Modal>
  );
};

const Hero = () => {
  const { textInfo } = useEssential();
  const { admin, links } = useEssential();
  const {
    isOpen: isEditOpen,
    onOpen: onEditOpen,
    onOpenChange: onEditOpenChange,
  } = useDisclosure();

  return (
    <section className="relative h-screen w-full max-w-full bg-gradient-to-r from-gray-100 via-gray-200 to-gray-300 overflow-hidden">
      <div
        className={`${admin.token ? "" : "hidden"} absolute p-2 right-16 z-40 top-36 bg-gradient-to-tr from-blue-500 to-green-500 rounded-lg`}
        onClick={() => {
          onEditOpen();
        }}
      >
        <IoSettings size={"40px"} color="white" />
      </div>
      <HeroEditMenu isOpen={isEditOpen} onOpenChange={onEditOpenChange} />
      {/* Hero Content */}
      <div className="relative z-10 flex flex-col items-center justify-center text-gray-800 h-full text-center">
        <motion.h1
          className="text-5xl font-bold drop-shadow-md"
          initial={{ opacity: 0, y: -50 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1 }}
        >
          {textInfo.landingInfos.HeroTitle}
        </motion.h1>
        <motion.p
          className="text-lg mt-4 max-w-3xl drop-shadow-sm"
          initial={{ opacity: 0, y: 50 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1.5 }}
        >
          {textInfo.landingInfos.HeroSubtitle}
        </motion.p>
        <motion.div
          className="mt-8 flex gap-4"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 1.5 }}
        >
          <Link to={links.aboutUrl.link}>
            <button
              className={`px-2 border-1 w-40 shadow-md border-neutral-700 hover:bg-neutral-100 hover:brightness-105 hover:translate-y-[-2px] py-2 text-lg font-semibold bg-pastel-green-300 text-gray-800 rounded-full hover:bg-pastel-green-400 transition-all`}
            >
              About Lab
            </button>
          </Link>

          <Link to={links.peopleUrl.link}>
            <button
              className={`px-2 border-1 w-40 shadow-md border-neutral-700 hover:bg-neutral-100 hover:brightness-105 hover:translate-y-[-2px] py-2 text-lg font-semibold bg-pastel-green-300 text-gray-800 rounded-full hover:bg-pastel-green-400 transition-all`}
            >
              About People
            </button>
          </Link>
        </motion.div>
      </div>
    </section>
  );
};

export default Hero;
