import React, { useState, useEffect } from "react";
import PublicationItem from "../componants/PublicationItem";
import { useNavigate, useParams } from "react-router-dom";
import { Button, Divider } from "@heroui/react";
import PatentItem from "../componants/PatentItem";
import PageHero from "../componants/PageHero";
import { Breadcrumbs, BreadcrumbItem } from "@heroui/react";
import useEssential from "../hooks/useEssential";
import { IoSettings } from "react-icons/io5";

const Publication = () => {
  const [publications, setPublications] = useState([]);
  const { links } = useEssential();
  const [patents, setPatents] = useState([]);
  const [activeTab, setActiveTab] = useState("publications");
  const { type } = useParams();
  const { admin } = useEssential();

  useEffect(() => {
    if (type) {
      setActiveTab(type);
    }
  }, [type]);

  useEffect(() => {
    fetch("/datas/textInfos.json")
      .then((response) => response.json())
      .then((data) => {
        if (activeTab === "publications") {
          setPublications(data.PublicationInfos);
        } else if (activeTab === "patents") {
          setPatents(data.patentInfos);
        }
      })
      .catch((error) => console.error("Error fetching data:", error));
  }, [activeTab]);

  return (
    <>
      <div className="min-h-screen w-full h-full">
        <PageHero
          name="Publication"
          activeTab={activeTab}
          setActiveTab={setActiveTab}
          navigations={links.pubUrl.navigations}
        ></PageHero>
        <section className="bg-gray-100 flex flex-col justify-center p-8 md:p-24 md:pt-8">
          <div className="flex flex-col w-full p-8">
            <div className="flex flex-col mt-6">
              <Divider className="w-44 h-1 border-4 border-gray-800 mb-4" />
              {activeTab === "publications" &&
                publications.map((pub, index) => (
                  <PublicationItem key={index} {...pub} />
                ))}
              {activeTab === "patents" &&
                patents.map((patent, index) => (
                  <PatentItem key={index} {...patent} />
                ))}
            </div>
          </div>
        </section>
      </div>
    </>
  );
};

export default Publication;
