import React, { useEffect, useState } from "react";
import {
  BrowserRouter as Router,
  Route,
  Routes,
  useNavigate,
} from "react-router-dom";
import { RecoilRoot } from "recoil";
import Home from "./pages/Home";
import About from "./pages/About";
import DefaultLayout from "./layouts/DefaultLayout";
import useEssential from "./hooks/useEssential";
import { HeroUIProvider } from "@heroui/react";
import Publication from "./pages/Publication";
import People from "./pages/People";
import NoticeBoard from "./pages/NoticeBoard";
import Callback from "./pages/Callback";

function App() {
  const { links, setLinks } = useEssential();
  const { admin, setAdmin } = useEssential();

  return (
    <HeroUIProvider>
      <RecoilRoot>
        <Router>
          <DefaultLayout>
            <Routes>
              <Route path={links["homeUrl"]?.link || "/"} element={<Home />} />
              <Route
                path={links["aboutUrl"]?.link || "/about"}
                element={<About />}
              />
              <Route
                path={links["pubUrl"]?.link || "/publication"}
                element={<Publication />}
              />
              <Route
                path={links["peopleUrl"]?.link || "/people"}
                element={<People />}
              />
              <Route
                path={links["noticeUrl"]?.link || "/noticeboard"}
                element={<NoticeBoard />}
              />
              <Route path="/callback" element={<Callback />} />
            </Routes>
          </DefaultLayout>
        </Router>
      </RecoilRoot>
    </HeroUIProvider>
  );
}

export default App;
