import React, { useEffect, useState } from "react";
import { Breadcrumbs, BreadcrumbItem } from "@heroui/react";
import { useNavigate, useParams } from "react-router-dom";

const Navigation = ({ navigationInfo, activeTab, setActiveTab }) => {
  useEffect(() => {
    console.log(navigationInfo);
  }, [navigationInfo]);

  useEffect(() => {
    console.log(activeTab);
  }, [activeTab]);

  return (
    <div className="flex flex-col items-start pl-16 text-sm bg-black bg-opacity-30 z-30 p-4 w-full">
      <Breadcrumbs
        itemClasses={{
          separator: "px-2",
        }}
        separator="/"
      >
        {navigationInfo.map((item) => (
          <BreadcrumbItem
            key={item.key}
            isCurrent={activeTab === item.key}
            className={`cursor-pointer font-normal ${activeTab === item.key ? "font-semibold text-white" : ""}`}
            onClick={() => setActiveTab(item.key)}
          >
            {item.text}
          </BreadcrumbItem>
        ))}
      </Breadcrumbs>
    </div>
  );
};

export default Navigation;
