import React, { useEffect } from "react";
import PropTypes from "prop-types";
import Header from "./Header";
import Footer from "./Footer";
import useEssential from "../hooks/useEssential";
import AdminMenu from "../componants/AdminMenu";
import { useLocation } from "react-router-dom";

function DefaultLayout(props) {
  const { admin, setAdmin } = useEssential();
  const { links, setLinks } = useEssential();
  const { textInfo, setTextInfo } = useEssential();

  const location = useLocation();

  useEffect(() => {
    console.log(admin);
  }, [admin]);

  const fetchSettings = () => {
    console.log("Fetching settings");
    fetch("/datas/links.json")
      .then((response) => response.json())
      .then((data) => {
        Object.keys(links).forEach((key) => {
          setLinks((prev) => {
            return { ...prev, [key]: { ...prev[key], ...data[key] } };
          });
        });
      });
    fetch("/datas/textInfos.json")
      .then((response) => response.json())
      .then((data) => {
        setTextInfo(data);
      });
  };

  useEffect(() => {
    fetchSettings();
    if (
      sessionStorage.getItem("token") != "" &&
      sessionStorage.getItem("user") != ""
    ) {
      console.log("Admin logged in", {
        token: sessionStorage.getItem("token"),
        user: sessionStorage.getItem("user"),
      });
      setAdmin({
        token: sessionStorage.getItem("token"),
        user: sessionStorage.getItem("user"),
      });
    }
  }, [location]);

  useEffect(() => {
    fetchSettings();
  }, []);

  return (
    <>
      <Header />

      <div>
        <AdminMenu />
        {props.children}
      </div>

      <Footer />
    </>
  );
}

DefaultLayout.propTypes = {
  children: PropTypes.node.isRequired,
};

export default DefaultLayout;
