import React, { useEffect, useState } from "react";
import {
  Modal,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  useDisclosure,
  useDraggable,
  Input,
} from "@heroui/react";
import useEssential from "../../hooks/useEssential";
import useCommit from "../../hooks/useCommit";

export default function LinkSettingMenu({ isOpen, onOpen, onOpenChange }) {
  const { admin } = useEssential();
  const targetRef = React.useRef(null);
  const { moveProps } = useDraggable({ targetRef, isDisabled: !isOpen });
  const { links, setLinks } = useEssential();
  const [expanded, setExpanded] = useState({});

  const toggleExpand = (key) => {
    setExpanded((prev) => {
      const newExpanded = { ...prev, [key]: !prev[key] };
      Object.keys(newExpanded).forEach((k) => {
        if (k !== key) {
          newExpanded[k] = false;
        }
      });
      return newExpanded;
    });
  };
  const { updateFiles } = useCommit();

  const onSave = () => {
    console.log(JSON.stringify(links, null, 2));
    updateFiles(
      [
        {
          action: "add",
          path: "datas/links.json",
          content: JSON.stringify(links, null, 2),
        },
      ],
      "Update links"
    );
  };

  useEffect(() => {
    console.log(links);
  }, [links]);

  return (
    <>
      <Modal
        isDismissable={false}
        isKeyboardDismissDisabled={true}
        ref={targetRef}
        isOpen={isOpen}
        onOpenChange={onOpenChange}
        backdrop="transparent"
        hideCloseButton
        classNames={{
          body: "py-6 p-4 bg-neutral-100",
          base: "relative pointer-events-auto flex border-gray-300 bg-white text-gray-800 max-w-[600px] shadow-lg",
          header: "border-b-[1px] border-gray-300 p-2 ",
          footer: "border-t-[1px] border-gray-300 p-2",
          closeButton: "hover:bg-gray-100 active:bg-gray-200",
          wrapper: "pointer-events-none overflow-auto z-50",
        }}
      >
        <ModalContent>
          {(onClose) => (
            <>
              <ModalHeader {...moveProps} className="flex flex-col gap-1">
                LINKS
              </ModalHeader>
              <ModalBody>
                <div className="relative w-full">
                  {Object.keys(links).map((key) => (
                    <div
                      key={key}
                      className="mb-4 rounded-md p-1 bg-white transition-all"
                    >
                      <div className="flex justify-between items-center">
                        <label className="block text-sm font-semibold text-gray-700">
                          {key}
                        </label>
                        <button
                          onClick={() => toggleExpand(key)}
                          className="text-blue-500"
                        >
                          {expanded[key] ? "Collapse" : "Expand"}
                        </button>
                      </div>
                      {expanded[key] && (
                        <div className="p-2">
                          <div className=" flex flex-row gap-2 items-center justify-center">
                            <label className="block text-sm font-medium text-gray-700">
                              Title:
                            </label>
                            <input
                              type="text"
                              value={links[key].text}
                              onChange={(e) =>
                                setLinks((prev) => ({
                                  ...prev,
                                  [key]: {
                                    ...prev[key],
                                    text: e.target.value,
                                  },
                                }))
                              }
                              className="bg-neutral-50 p-1 focus:border-[1px] block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm"
                            />
                            <label className="block text-sm font-medium text-gray-700 ">
                              Link
                            </label>
                            <input
                              type="text"
                              value={links[key].link}
                              onChange={(e) =>
                                setLinks((prev) => ({
                                  ...prev,
                                  [key]: {
                                    ...prev[key],
                                    link: e.target.value,
                                  },
                                }))
                              }
                              className="bg-neutral-50 p-1 focus:border-[1px] block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm"
                            />
                          </div>

                          <label className="inline-flex items-center mt-2">
                            <input
                              type="checkbox"
                              checked={links[key].activate}
                              onChange={(e) =>
                                setLinks((prev) => ({
                                  ...prev,
                                  [key]: {
                                    ...prev[key],
                                    activate: e.target.checked,
                                  },
                                }))
                              }
                              className="form-checkbox"
                            />
                            <span className="ml-2">Activate</span>
                          </label>
                          {links[key].navigations && (
                            <div className="ml-4 mt-2">
                              {links[key].navigations.map((nav) => (
                                <div key={nav.key} className="mb-2">
                                  <label className="block text-sm font-medium text-gray-700">
                                    {nav.text}
                                  </label>
                                  <label className="inline-flex items-center mt-1">
                                    <input
                                      type="checkbox"
                                      checked={nav.activate}
                                      onChange={(e) =>
                                        setLinks((prev) => ({
                                          ...prev,
                                          [key]: {
                                            ...prev[key],
                                            navigations: prev[
                                              key
                                            ].navigations.map((n) =>
                                              n.key === nav.key
                                                ? {
                                                    ...n,
                                                    activate: e.target.checked,
                                                  }
                                                : n
                                            ),
                                          },
                                        }))
                                      }
                                      className="form-checkbox"
                                    />
                                    <span className="ml-2">Activate</span>
                                  </label>
                                </div>
                              ))}
                            </div>
                          )}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </ModalBody>
              <ModalFooter>
                <Button color="primary" onPress={onSave}>
                  Save
                </Button>
                <Button color="danger" variant="light" onPress={onClose}>
                  Close
                </Button>
              </ModalFooter>
            </>
          )}
        </ModalContent>
      </Modal>
    </>
  );
}
