import React, { useState } from "react";
import {
  Modal,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
} from "@heroui/react";
import MarkdownEditor from "@uiw/react-md-editor";
import { useEffect } from "react";
import { BiImageAdd } from "react-icons/bi";

export default function MarkdownEditorModal({
  isOpen,
  onOpenChange,
  initialMarkdown,
  applyMarkdown,
}) {
  const [markdown, setMarkdown] = useState(initialMarkdown || "");
  const [Images, setImages] = useState([]);

  useEffect(() => {
    setMarkdown(initialMarkdown);
  }, [initialMarkdown]);

  useEffect(() => {
    const fetchImages = async () => {
      try {
        const response = await fetch("/datas/imageInfos.json");
        const images = await response.json();
        setImages(images.imageInfos);
      } catch (error) {
        console.error("Error fetching images:", error);
      }
    };

    fetchImages();
  }, []);

  const copyToClipboard = (text) => {
    navigator.clipboard.writeText(text).then(
      () => {
        console.log("Copied to clipboard successfully!");
      },
      (err) => {
        console.error("Could not copy text: ", err);
      }
    );
  };

  return (
    <Modal
      isOpen={isOpen}
      onOpenChange={onOpenChange}
      hideCloseButton
      classNames={{
        body: "py-6 p-4 bg-neutral-100",
        base: "relative pointer-events-auto flex border-gray-300 bg-white text-gray-800 max-w-[800px] shadow-lg",
        header: "border-b-[1px] border-gray-300 p-2",
        footer: "border-t-[1px] border-gray-300 p-2",
        closeButton: "hover:bg-gray-100 active:bg-gray-200",
        wrapper: "pointer-events-none overflow-auto z-50",
      }}
    >
      <ModalContent>
        {(onClose) => (
          <>
            <ModalHeader>
              <h2>Markdown Editor</h2>
            </ModalHeader>
            <ModalBody>
              <div className="flex flex-row w-full gap-2">
                <MarkdownEditor
                  value={markdown}
                  onChange={setMarkdown}
                  height="400px"
                  className="w-full"
                />
                <div className="w-48 h-[400px] overflow-y-auto flex flex-col gap-2 p-1  rounded-md bg-neutral-200">
                  {Images.map((image, index) => (
                    <div
                      className="w-32 aspect-square"
                      key={index}
                      onClick={() =>
                        copyToClipboard(`![${image.name}](${image.url})`)
                      }
                    >
                      {image.url === "null" ? (
                        <div className="w-full h-full rounded-md bg-neutral-100 flex items-center justify-center">
                          <BiImageAdd size={"80px"} />
                        </div>
                      ) : (
                        <img
                          src={image.url}
                          alt={image.name}
                          className="object-cover w-full h-full rounded-md"
                        />
                      )}
                    </div>
                  ))}
                </div>
              </div>
            </ModalBody>
            <ModalFooter>
              <Button
                color="primary"
                onPress={() => {
                  applyMarkdown(markdown);
                  onClose();
                }}
              >
                Apply
              </Button>
              <Button color="primary" onPress={onClose}>
                Close
              </Button>
            </ModalFooter>
          </>
        )}
      </ModalContent>
    </Modal>
  );
}
