import React from "react";
import {
  Modal,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  useDisclosure,
  useDraggable,
} from "@heroui/react";
import useEssential from "../hooks/useEssential";
import LinkSettingMenu from "./Menus/linkSettingMenu";
import ImageSettingMenu from "./Menus/ImageSettingMenu";
import PeopleSettingMenu from "./Menus/PeopleSettingMenu";
import PublicationSettingMenu from "./Menus/publicationSettingMenu";
import NoticeSettingMenu from "./Menus/noticeSettingMenu";
import FooterSettingMenu from "./Menus/footerSettingMenu";

export default function AdminMenu() {
  const { admin } = useEssential();
  const { isOpen, onOpen, onOpenChange } = useDisclosure();
  const targetRef = React.useRef(null);
  const { moveProps } = useDraggable({ targetRef, isDisabled: !isOpen });

  const {
    isOpen: isLinkSettingOpen,
    onOpen: onLinkSettingOpen,
    onOpenChange: onLinkSettingOpenChange,
  } = useDisclosure();

  const {
    isOpen: isImageSettingOpen,
    onOpen: onImageSettingOpen,
    onOpenChange: onImageSettingOpenChange,
  } = useDisclosure();

  const {
    isOpen: isPeopleSettingOpen,
    onOpen: onPeopleSettingOpen,
    onOpenChange: onPeopleSettingOpenChange,
  } = useDisclosure();

  const {
    isOpen: isPublicationSettingOpen,
    onOpen: onPublicationSettingOpen,
    onOpenChange: onPublicationSettingOpenChange,
  } = useDisclosure();

  const {
    isOpen: isNoticeSettingOpen,
    onOpen: onNoticeSettingOpen,
    onOpenChange: onNoticeSettingOpenChange,
  } = useDisclosure();

  const {
    isOpen: isFooterSettingOpen,
    onOpen: onFooterSettingOpen,
    onOpenChange: onFooterSettingOpenChange,
  } = useDisclosure();

  return (
    <>
      <FooterSettingMenu
        isOpen={isFooterSettingOpen}
        onOpen={onFooterSettingOpen}
        onOpenChange={onFooterSettingOpenChange}
      />
      <LinkSettingMenu
        isOpen={isLinkSettingOpen}
        onOpen={onLinkSettingOpen}
        onOpenChange={onLinkSettingOpenChange}
      />
      <ImageSettingMenu
        isOpen={isImageSettingOpen}
        onOpen={onImageSettingOpen}
        onOpenChange={onImageSettingOpenChange}
      />
      <PeopleSettingMenu
        isOpen={isPeopleSettingOpen}
        onOpen={onPeopleSettingOpen}
        onOpenChange={onPeopleSettingOpenChange}
      />
      <PublicationSettingMenu
        isOpen={isPublicationSettingOpen}
        onOpen={onPublicationSettingOpen}
        onOpenChange={onPublicationSettingOpenChange}
      />
      <NoticeSettingMenu
        isOpen={isNoticeSettingOpen}
        onOpen={onNoticeSettingOpen}
        onOpenChange={onNoticeSettingOpenChange}
      />
      <div
        className={`fixed right-7 bottom-7 z-50  ${admin.token ? "" : "hidden"}`}
      >
        <Button
          className={`bg-gradient-to-tr from-blue-500 to-green-500 text-white shadow-lg p-2 rounded-md `}
          size="md"
          onClick={onOpen}
        >
          Open Modal
        </Button>
      </div>
      <Modal
        isDismissable={false}
        isKeyboardDismissDisabled={true}
        ref={targetRef}
        isOpen={isOpen}
        onOpenChange={onOpenChange}
        backdrop="transparent"
        hideCloseButton
        classNames={{
          body: "py-6 p-4",
          base: "relative pointer-events-auto flex border-gray-300 bg-white text-gray-800 max-w-[600px] shadow-lg",
          header: "border-b-[1px] border-gray-300 p-2 ",
          footer: "border-t-[1px] border-gray-300 p-2",
          closeButton: "hover:bg-gray-100 active:bg-gray-200",
          wrapper: "pointer-events-none overflow-auto z-50",
        }}
      >
        <ModalContent>
          {(onClose) => (
            <>
              <ModalHeader {...moveProps} className="flex flex-col gap-1">
                Settings
              </ModalHeader>
              <ModalBody>
                <div className="relative w-full">
                  <Button
                    className="bg-blue-500 rounded-md p-2 text-white"
                    onClick={onLinkSettingOpen}
                  >
                    링크 설정
                  </Button>
                  <Button
                    className="bg-blue-500 rounded-md p-2 text-white"
                    onClick={onImageSettingOpen}
                  >
                    이미지 업로드 및 조회
                  </Button>
                  <Button
                    className="bg-blue-500 rounded-md p-2 text-white"
                    onClick={onPeopleSettingOpen}
                  >
                    People 설정
                  </Button>
                  <Button
                    className="bg-blue-500 rounded-md p-2 text-white"
                    onClick={onPublicationSettingOpen}
                  >
                    Publication 설정
                  </Button>
                  <Button
                    className="bg-blue-500 rounded-md p-2 text-white"
                    onClick={onNoticeSettingOpen}
                  >
                    Notice 설정
                  </Button>
                  <Button
                    className="bg-blue-500 rounded-md p-2 text-white"
                    onClick={onFooterSettingOpen}
                  >
                    Footer 설정
                  </Button>
                </div>
              </ModalBody>
              <ModalFooter>
                <Button color="primary" onPress={onClose}>
                  Save
                </Button>
                <Button color="danger" variant="light" onPress={onClose}>
                  Close
                </Button>
              </ModalFooter>
            </>
          )}
        </ModalContent>
      </Modal>
    </>
  );
}
