import React from "react";
import { FaLink, FaEnvelope } from "react-icons/fa";
import { PiLinkSimpleHorizontal } from "react-icons/pi";

const ResearcherCard = ({
  name,
  title,
  email,
  description,
  imageSrc,
  type,
  affiliations,
  cvLink,
}) => {
  const handleCvClick = (cvLink) => {
    if (cvLink) {
      window.open(cvLink, "_blank", "noopener,noreferrer");
    }
  };

  return (
    <>
      {type === "Professor" ? (
        <article className="bg-white border border-gray-300 flex p-1 relative hover:shadow-lg hover:translate-y-[-5px] transition-all duration-300 filter hover:brightness-105">
          <div className="border-r border-gray-300 flex flex-col justify-center p-1">
            <img
              src={imageSrc !== "null" ? imageSrc : "/images/person.png"}
              alt={`${name}`}
              className="object-contain object-center w-[279px]"
            />
          </div>
          <div className="flex flex-col items-start m-auto ml-8 text-lg font-sans">
            {cvLink && (
              <div
                className="absolute top-2 right-2 bg-white border border-gray-300 p-2 z-10 w-12 h-12 flex justify-center items-center hover:shadow-lg transition-all duration-300 hover:bg-gray-300"
                onClick={() => handleCvClick(cvLink)}
              >
                <PiLinkSimpleHorizontal className="w-8 h-8 m-auto filter invert-[70%] hover:invert-0 transition-all duration-300" />
              </div>
            )}
            <h2 className="text-[#00637c] text-3xl font-extrabold">{name}</h2>
            <p className="text-black font-medium mt-2 ">{title}</p>
            <ul className="border-t border-gray-400 self-stretch flex flex-col items-start mt-6 w-full pt-4">
              <li className="flex gap-3 mb-4">
                <span className="text-gray-700 font-light">
                  {description.split("\n").map((line, index) => (
                    <React.Fragment key={index}>
                      {line}
                      <br />
                    </React.Fragment>
                  ))}
                </span>
              </li>
              <li className="flex gap-3 mb-4">
                <FaEnvelope className="w-7 h-7" />
                <span className="text-gray-700 font-bold">CONTACT</span>
                <span className="text-gray-800 font-light">{email}</span>
              </li>
            </ul>
          </div>
        </article>
      ) : (
        <article className="bg-white border border-gray-300 flex p-1 relative hover:shadow-lg hover:translate-y-[-5px] transition-all duration-300 filter hover:brightness-105">
          <div className="border-r border-gray-300 flex flex-col justify-center p-1">
            <img
              src={imageSrc !== "null" ? imageSrc : "/images/person.png"}
              alt={`${name}`}
              className="aspect-[0.81] object-contain object-center w-[219px]"
            />
          </div>
          <div className="flex flex-col items-start m-auto ml-8 text-base font-sans">
            {cvLink && (
              <div
                className="absolute top-2 right-2 bg-white border border-gray-300 p-2 z-10 w-12 h-12 flex justify-center items-center hover:shadow-lg transition-all duration-300 hover:bg-gray-300"
                onClick={() => handleCvClick(cvLink)}
              >
                <PiLinkSimpleHorizontal className="w-8 h-8 m-auto filter invert-[70%] hover:invert-0 transition-all duration-300" />
              </div>
            )}
            <h2 className="text-[#00407c] text-2xl font-bold">{name}</h2>
            <p className="text-gray-500 font-medium mt-2">{title}</p>
            <ul className="border-t border-gray-200 self-stretch flex flex-col items-start mt-6 w-full pt-4">
              <li className="flex gap-3 mb-4">
                <span className="text-gray-800 font-light">
                  {description.split("\n").map((line, index) => (
                    <React.Fragment key={index}>
                      {line}
                      <br />
                    </React.Fragment>
                  ))}
                </span>
              </li>
              {affiliations && (
                <li className="flex gap-3 mb-4">
                  <span className="text-gray-700 font-bold">AFFILIATIONS</span>
                  <span className="text-gray-800 font-light">
                    {affiliations}
                  </span>
                </li>
              )}
              <li className="flex gap-3 mb-4">
                <FaEnvelope className="w-7 h-7" />
                <span className="text-gray-700 font-bold">CONTACT</span>
                <span className="text-gray-800 font-light">{email}</span>
              </li>
            </ul>
          </div>
        </article>
      )}
    </>
  );
};

export default ResearcherCard;
