import React, { useEffect, useState } from "react";
import {
  Modal,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  useDraggable,
  Input,
} from "@heroui/react";
import useEssential from "../../hooks/useEssential";
import useCommit from "../../hooks/useCommit";
import { useDisclosure } from "@heroui/react";

export default function FooterSettingMenu({ isOpen, onOpen, onOpenChange }) {
  const { admin } = useEssential();
  const targetRef = React.useRef(null);
  const { moveProps } = useDraggable({ targetRef, isDisabled: !isOpen });
  const { updateFiles } = useCommit();
  const { textInfo, setTextInfo } = useEssential();
  const [footerInfo, setFooterInfo] = useState(textInfo.footerInfo);

  useEffect(() => {
    setFooterInfo(textInfo.footerInfo);
  }, [textInfo.footerInfo]);

  const onSave = async () => {
    let textInfoTmp = JSON.parse(
      JSON.stringify({
        ...textInfo,
        footerInfo: footerInfo,
      })
    );
    await updateFiles(
      [
        {
          action: "add",
          path: "datas/textInfos.json",
          content: JSON.stringify(textInfoTmp, null, 2),
        },
      ],
      "Update footer info"
    );
    alert("성공적으로 저장하였습니다. 적용에는 5분정도 소요됩니다.");
  };

  const handleInputChange = (field, value) => {
    setFooterInfo((prev) => ({
      ...prev,
      [field]: value,
    }));
  };

  return (
    <Modal
      isDismissable={false}
      isKeyboardDismissDisabled={true}
      ref={targetRef}
      isOpen={isOpen}
      onOpenChange={onOpenChange}
      backdrop="transparent"
      hideCloseButton
      classNames={{
        body: "py-6 p-4 bg-neutral-100",
        base: "relative pointer-events-auto flex border-gray-300 bg-white text-gray-800 max-w-[600px] shadow-lg",
        header: "border-b-[1px] border-gray-300 p-2 ",
        footer: "border-t-[1px] border-gray-300 p-2",
        closeButton: "hover:bg-gray-100 active:bg-gray-200",
        wrapper: "pointer-events-none overflow-auto z-50",
      }}
    >
      <ModalContent>
        {(onClose) => (
          <>
            <ModalHeader {...moveProps} className="flex flex-col gap-1">
              <div className="flex justify-between">
                <h2 className="text-lg font-semibold">Footer Settings</h2>
              </div>
            </ModalHeader>
            <ModalBody>
              <div className="flex flex-col gap-2">
                <label className="block text-sm font-medium text-gray-700">
                  Address:
                </label>
                <input
                  className="bg-neutral-100 p-2 py-1 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  value={footerInfo.address}
                  onChange={(e) => handleInputChange("address", e.target.value)}
                />
                <label className="block text-sm font-medium text-gray-700">
                  Email:
                </label>
                <input
                  className="bg-neutral-100 p-2 py-1 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  value={footerInfo.email}
                  onChange={(e) => handleInputChange("email", e.target.value)}
                />
              </div>
            </ModalBody>
            <ModalFooter>
              <Button color="primary" onPress={onSave}>
                Save
              </Button>
              <Button color="danger" variant="light" onPress={onClose}>
                Close
              </Button>
            </ModalFooter>
          </>
        )}
      </ModalContent>
    </Modal>
  );
}
