import React, { useEffect } from "react";
import CustomText from "../customComponants/customText";
import { IoSettings } from "react-icons/io5";
import useEssential from "../hooks/useEssential";
import NewsPublications from "./newsContent";
import { useDisclosure } from "@heroui/react";
import {
  Modal,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  useDraggable,
  Input,
} from "@heroui/react";
import useCommit from "../hooks/useCommit";
import MarkdownEditor from "./markdownEditor";
import { useState } from "react";

const EditDataModal = ({ isOpen, onOpenChange }) => {
  const { textInfo, setTextInfo } = useEssential();
  const { updateFiles } = useCommit();
  const targetRef = React.useRef(null);

  const [editTarget, setEditTarget] = useState(null);

  const [landingInfos, setLandingInfos] = useState(textInfo.landingInfos);

  useEffect(() => {
    console.log(landingInfos, editTarget, landingInfos[editTarget]);
  }, [landingInfos, editTarget]);

  const {
    isOpen: isEditorOpen,
    onOpen: onEditorOpen,
    onOpenChange: onEditorOpenChange,
  } = useDisclosure();

  const onSave = async () => {
    let textInfoTmp = JSON.parse(
      JSON.stringify({
        ...textInfo,
        landingInfos: landingInfos,
      })
    );
    setTextInfo(textInfoTmp);
    await updateFiles(
      [
        {
          action: "add",
          path: "datas/textInfos.json",
          content: JSON.stringify(textInfoTmp, null, 2),
        },
      ],
      "Update notice infos"
    );
    alert("성공적으로 저장하였습니다. 적용에는 5분정도 소요됩니다.");
  };

  return (
    <>
      <MarkdownEditor
        initialMarkdown={landingInfos[editTarget]}
        applyMarkdown={(markdown) => {
          setLandingInfos((prev) => {
            let newLandingInfos = { ...prev };
            newLandingInfos[editTarget] = markdown;
            return newLandingInfos;
          });
        }}
        isOpen={isEditorOpen}
        onOpenChange={onEditorOpenChange}
      />

      <Modal
        isDismissable={false}
        isKeyboardDismissDisabled={true}
        ref={targetRef}
        isOpen={isOpen}
        onOpenChange={onOpenChange}
        backdrop="transparent"
        hideCloseButton
        classNames={{
          body: "py-6 p-4 bg-neutral-100",
          base: "relative pointer-events-auto flex border-gray-300 bg-white text-gray-800 max-w-[600px] shadow-lg",
          header: "border-b-[1px] border-gray-300 p-2 ",
          footer: "border-t-[1px] border-gray-300 p-2",
          closeButton: "hover:bg-gray-100 active:bg-gray-200",
          wrapper: "pointer-events-none overflow-auto z-50",
        }}
      >
        <ModalContent>
          {(onClose) => (
            <>
              <ModalHeader className="flex flex-col gap-1">
                <div className="flex justify-between">
                  <h2 className="text-lg font-semibold">Landing Infos</h2>
                </div>
              </ModalHeader>
              <ModalBody>
                <Button
                  color="primary"
                  className="bg-blue-500 rounded-md p-2 text-white"
                  onPress={() => {
                    setEditTarget("aboutus");
                    onEditorOpen();
                  }}
                >
                  AboutUs 편집
                </Button>
                <Button
                  color="primary"
                  className="bg-blue-500 rounded-md p-2 text-white"
                  onPress={() => {
                    setEditTarget("researchArea");
                    onEditorOpen();
                  }}
                >
                  AboutUs 편집
                </Button>
              </ModalBody>
              <ModalFooter>
                <Button color="primary" onPress={onSave}>
                  Save All
                </Button>
                <Button color="danger" variant="light" onPress={onClose}>
                  Close
                </Button>
              </ModalFooter>
            </>
          )}
        </ModalContent>
      </Modal>
    </>
  );
};

function AboutUs() {
  const { admin } = useEssential();
  const { textInfo } = useEssential();
  const {
    isOpen: isEditOpen,
    onOpen: onEditOpen,
    onOpenChange: onEditOpenChange,
  } = useDisclosure();
  return (
    <div className="relative w-screen flex justify-center items-center pt-20 px-10 mobile:px-4 fade-wrap">
      <div
        className={`${admin.token ? "" : "hidden"} absolute p-2 right-16 top-16 bg-gradient-to-tr from-blue-500 to-green-500 rounded-lg`}
        onClick={() => {
          onEditOpen();
        }}
      >
        <IoSettings size={"40px"} color="white" />
      </div>
      <EditDataModal isOpen={isEditOpen} onOpenChange={onEditOpenChange} />
      <div className="relative p-4 text-center mobile:p-2">
        <h3 className="text-2xl font-extrabold mb-10 text-teal-700 font-iceland mobile:text-xl">
          ABOUT US
        </h3>
        <CustomText
          markdown={textInfo.landingInfos.aboutus}
          className="text-5xl leading-snug mobile:text-3xl"
          fontSize="text-5xl"
          id="intro-text"
        />
      </div>
    </div>
  );
}

