import React, { useEffect } from "react";
import Hero from "../componants/Hero"; // Ensure 'components' folder name is correct
import LandingContent from "../componants/LandingContent"; // Ensure 'components' folder name is correct
import { useNavigate } from "react-router-dom";

function Home() {
  const navigate = useNavigate();

  useEffect(() => {
    const redirectPath = sessionStorage.getItem("redirect_path");
    if (redirectPath) {
      navigate(redirectPath);
      sessionStorage.removeItem("redirect_path");
    }
  }, [navigate]);
  useEffect(() => {
    const handleScroll = (event) => {
      if (window.scrollY === 0 && event.deltaY > 0) {
        window.scrollTo({
          top: window.innerHeight,
          behavior: "smooth",
        });
      } else if (window.scrollY <= window.innerHeight && event.deltaY < 0) {
        window.scrollTo({
          top: 0,
          behavior: "smooth",
        });
      }
    };

    window.addEventListener("wheel", handleScroll, { passive: false });
    return () => {
      window.removeEventListener("wheel", handleScroll);
    };
  }, []);

  return (
    <div id="homeRoot" className="max-w-[100vw] overflow-hidden">
      <Hero />
      <LandingContent />
    </div>
  );
}

export default Home;
