import React, { useEffect, useState } from "react";
import {
  Modal,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  useDraggable,
  Input,
} from "@heroui/react";
import { BiImageAdd } from "react-icons/bi";
import useEssential from "../../hooks/useEssential";
import useCommit from "../../hooks/useCommit";
import ImageResizeModal from "../ImageResizeModal";

export default function ImageSettingMenu({ isOpen, onOpen, onOpenChange }) {
  const { admin } = useEssential();
  const targetRef = React.useRef(null);
  const { moveProps } = useDraggable({ targetRef, isDisabled: !isOpen });
  const { updateFiles } = useCommit();
  const [Images, setImages] = useState([]);
  const [selectedImage, setSelectedImage] = useState(null);
  const [newImage, setNewImage] = useState([]);
  const [isDragging, setIsDragging] = useState(false);
  const [isResizeModalOpen, setIsResizeModalOpen] = useState(false);

  useEffect(() => {
    const fetchImages = async () => {
      try {
        const response = await fetch("/datas/imageInfos.json");
        const images = await response.json();
        setImages(images.imageInfos);
      } catch (error) {
        console.error("Error fetching images:", error);
      }
    };

    fetchImages();
  }, []);

  const getBase64FromImageFile = (file) => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result?.toString().split(",")[1]);
      reader.onerror = (error) => reject(error);
    });
  };

  const onSave = async () => {
    let ImageDatas = [];
    newImage.forEach(async (image) => {
      ImageDatas.push({
        path: `images/${image.name}.png`,
        content: await getBase64FromImageFile(image.file),
      });
    });

    ImageDatas.push({
      action: "add",
      path: "datas/imageInfos.json",
      content: JSON.stringify({ imageInfos: Images }, null, 2),
    });

    await updateFiles(ImageDatas, "Update image infos");
    alert("성공적으로 저장하였습니다. 적용에는 5분정도 소요됩니다.");
  };

  const handleFileChange = (event) => {
    const file = event.target.files?.[0];
    if (file) {
      updateImage(file);
    }
  };

  const handleDragOver = (event) => {
    event.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const handleDrop = (event) => {
    event.preventDefault();
    setIsDragging(false);
    const file = event.dataTransfer.files?.[0];

    if (file) {
      updateImage(file);
    }
  };

  const updateImage = (file) => {
    const reader = new FileReader();
    reader.onload = () => {
      setNewImage((prev) => [
        ...prev.filter((image) => image.name !== selectedImage.name),
        {
          imageLink: reader.result,
          file: file,
          name: selectedImage.name,
        },
      ]);
      setSelectedImage((prev) => ({
        ...prev,
        url: `images/${prev.name}.png`,
      }));
    };
    reader.readAsDataURL(file);
  };

  const handleDetailChange = (field, value) => {
    setSelectedImage((prev) => ({
      ...prev,
      [field]: value,
    }));
  };

  const addNewImage = () => {
    const newImageName = prompt("새로운 이미지의 이름을 적어주세요(영어)");
    if (newImageName) {
      setImages((prev) => [
        ...prev,
        {
          name: newImageName,
          url: `/images/${newImageName}.png`,
          category: "normal",
        },
      ]);
      setSelectedImage({ name: newImageName, url: "null", category: "normal" });
    }
  };

  const systemImages = Images.filter((image) => image.category === "system");
  const normalImages = Images.filter((image) => image.category === "normal");

  return (
    <>
      <Modal
        isDismissable={false}
        isKeyboardDismissDisabled={true}
        ref={targetRef}
        isOpen={isOpen}
        onOpenChange={onOpenChange}
        backdrop="transparent"
        hideCloseButton
        classNames={{
          body: "py-6 p-4 bg-neutral-100",
          base: "relative pointer-events-auto flex border-gray-300 bg-white text-gray-800 max-w-[800px] shadow-lg",
          header: "border-b-[1px] border-gray-300 p-2 ",
          footer: "border-t-[1px] border-gray-300 p-2",
          closeButton: "hover:bg-gray-100 active:bg-gray-200",
          wrapper: "pointer-events-none overflow-auto z-50",
        }}
      >
        <ModalContent>
          {(onClose) => (
            <>
              <ModalHeader {...moveProps} className="flex flex-col gap-1">
                IMAGES
              </ModalHeader>
              <ModalBody>
                <div className="relative w-full">
                  <div className="flex flex-row flex-wrap gap-4">
                    {selectedImage === null ? (
                      <>
                        <div className="w-full border-b-2 border-gray-300 my-4">
                          <h2 className="text-xl font-semibold">
                            System Images
                          </h2>
                        </div>
                        {systemImages.map((image, index) => (
                          <div
                            key={index}
                            className="flex flex-col gap-4 items-center p-2 shadow-md bg-white rounded-md hover:shadow-lg hover:translate-y-[-4px] hover:brightness-105 transition-all"
                            onClick={() => setSelectedImage(image)}
                          >
                            <div className="w-40 aspect-square">
                              <img
                                src={image.url}
                                alt={image.name}
                                className="object-cover w-full h-full rounded-md"
                              />
                            </div>
                            <div className="w-40">
                              <Input
                                classNames={{
                                  input: "text-lg font-bold text-center",
                                }}
                                value={image.name}
                                disabled
                              />
                              <h3 className="text-gray-500 font-normal text-center text-wrap break-words">
                                {image.url.replace("/images/", "")}
                              </h3>
                            </div>
                          </div>
                        ))}
                        <div className="w-full border-b-2 border-gray-300 my-4">
                          <h2 className="text-xl font-semibold">
                            Normal Images
                          </h2>
                        </div>
                        {normalImages.map((image, index) => (
                          <div
                            key={index}
                            className="flex flex-col gap-4 items-center p-2 shadow-md bg-white rounded-md hover:shadow-lg hover:translate-y-[-4px] hover:brightness-105 transition-all"
                            onClick={() => setSelectedImage(image)}
                          >
                            <div className="w-40 aspect-square">
                              {image.url === "null" ? (
                                <div className="w-full h-full rounded-md bg-neutral-100 flex items-center justify-center">
                                  <BiImageAdd size={"80px"} />
                                </div>
                              ) : newImage.find(
                                  (imageFnd) => imageFnd.name === image.name
                                ) ? (
                                <img
                                  src={
                                    newImage.find(
                                      (imageFnd) => imageFnd.name === image.name
                                    ).imageLink
                                  }
                                  alt={image.name}
                                  className="object-cover w-full h-full rounded-md"
                                />
                              ) : (
                                <img
                                  src={image.url}
                                  alt={image.name}
                                  className="object-cover w-full h-full rounded-md"
                                />
                              )}
                            </div>
                            <div className="w-40">
                              <Input
                                classNames={{
                                  input: "text-lg font-bold text-center",
                                }}
                                value={image.name}
                                disabled
                              />
                              <h3 className="text-gray-500 font-normal text-center text-wrap break-words">
                                {image.url.replace("/images/", "")}
                              </h3>
                            </div>
                          </div>
                        ))}
                        <div
                          className="flex flex-col gap-4 items-center p-2 shadow-md bg-white rounded-md hover:shadow-lg hover:translate-y-[-4px] hover:brightness-105 transition-all cursor-pointer"
                          onClick={addNewImage}
                        >
                          <div className="w-40 aspect-square">
                            <div className="w-full h-full rounded-md bg-neutral-100 flex items-center justify-center">
                              <BiImageAdd size={"80px"} />
                            </div>
                          </div>
                          <div className="w-40">
                            <Input
                              classNames={{
                                input: "text-lg font-bold text-center",
                              }}
                              value="New Image"
                              disabled
                            />
                            <h3 className="text-gray-500 font-normal text-center text-wrap break-words">
                              Add a new image
                            </h3>
                          </div>
                        </div>
                      </>
                    ) : (
                      <div className="flex flex-row gap-4 w-full">
                        <div className="flex flex-col items-center">
                          <label
                            className={`w-40 relative cursor-pointer ${
                              isDragging ? "border-2 border-blue-500" : ""
                            }`}
                            onDragOver={handleDragOver}
                            onDragLeave={handleDragLeave}
                            onDrop={handleDrop}
                          >
                            <input
                              type="file"
                              className="hidden"
                              onChange={handleFileChange}
                            />
                            {isDragging ? (
                              <div className="w-full h-full rounded-md aspect-[0.812] bg-gray-200 flex items-center justify-center">
                                <p className="text-gray-600">
                                  파일을 올려 불러오기
                                </p>
                              </div>
                            ) : selectedImage.url === "null" ? (
                              <div className="w-full h-full rounded-md bg-neutral-100 flex items-center justify-center">
                                <BiImageAdd size={"80px"} />
                              </div>
                            ) : newImage.find(
                                (image) => image.name === selectedImage.name
                              ) ? (
                              <img
                                src={
                                  newImage.find(
                                    (image) => image.name === selectedImage.name
                                  ).imageLink
                                }
                                alt={selectedImage.name}
                                className="object-cover w-full h-full rounded-md"
                              />
                            ) : (
                              <img
                                src={selectedImage.url}
                                alt={selectedImage.name}
                                className="object-cover w-full h-full rounded-md"
                              />
                            )}
                          </label>

                          <div className="flex flex-row justify-between gap-2 w-49">
                            {selectedImage.category !== "system" && (
                              <Button
                                variant="light"
                                className="mt-2 bg-neutral-300 w-full rounded-md"
                                onPress={() => {
                                  setNewImage((prev) =>
                                    prev.filter(
                                      (image) =>
                                        image.name !== selectedImage.name
                                    )
                                  );
                                  setSelectedImage((prev) => ({
                                    ...prev,
                                    url: "null",
                                  }));
                                }}
                              >
                                Reset
                              </Button>
                            )}
                            <Button
                              variant="light"
                              className="mt-2 bg-neutral-300 w-full rounded-md"
                              onPress={() => setIsResizeModalOpen(true)}
                            >
                              Edit
                            </Button>
                          </div>
                        </div>
                        <div className="flex flex-col gap-3 flex-1">
                          <div className="flex flex-row gap-2">
                            <h3 className=" text-nowrap ">이름: </h3>
                            <Input
                              defaultValue={selectedImage.name}
                              onChange={(e) =>
                                handleDetailChange("name", e.target.value)
                              }
                              disabled
                            />
                          </div>
                          <div className="flex flex-row gap-2">
                            <h3 className=" text-nowrap">설명: </h3>
                            <Input
                              defaultValue={selectedImage.description}
                              onChange={(e) =>
                                handleDetailChange(
                                  "description",
                                  e.target.value
                                )
                              }
                            />
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              </ModalBody>
              <ModalFooter>
                <Button
                  color="primary"
                  onPress={onSave}
                  className={`${selectedImage != null ? "hidden" : ""}`}
                >
                  Save
                </Button>
                <Button
                  color="danger"
                  variant="light"
                  className={`${selectedImage == null ? "hidden" : ""}`}
                  onPress={() => {
                    setImages((prev) =>
                      prev.map((image) =>
                        image.id === selectedImage.id ? selectedImage : image
                      )
                    );
                    setSelectedImage(null);
                  }}
                >
                  Apply
                </Button>
                <Button
                  color="danger"
                  variant="light"
                  onPress={() => {
                    onClose();
                    setSelectedImage(null);
                  }}
                >
                  Close
                </Button>
              </ModalFooter>
            </>
          )}
        </ModalContent>
      </Modal>
      {selectedImage && (
        <ImageResizeModal
          isOpen={isResizeModalOpen}
          onClose={() => setIsResizeModalOpen(false)}
          image={
            newImage.find((image) => image.name === selectedImage.name)
              ? newImage.find((image) => image.name === selectedImage.name)
                  .imageLink
              : selectedImage.url
          }
          onImageChange={(newImageUrl, newImageFile) => {
            console.log(newImageUrl, newImageFile);
            setNewImage((prev) =>
              prev.map((image) =>
                image.name === selectedImage.name
                  ? {
                      imageLink: newImageUrl,
                      file: newImageFile,
                      name: image.name,
                    }
                  : image
              )
            );
            setSelectedImage((prev) => ({
              ...prev,
              url: `images/${prev.name}.png`,
            }));
          }}
        />
      )}
    </>
  );
}
