import React, { useEffect, useState } from "react";
import {
  Modal,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  useDraggable,
  Input,
} from "@heroui/react";
import useEssential from "../../hooks/useEssential";
import useCommit from "../../hooks/useCommit";

export default function PublicationSettingMenu({
  isOpen,
  onOpen,
  onOpenChange,
}) {
  const { admin } = useEssential();
  const targetRef = React.useRef(null);
  const { moveProps } = useDraggable({ targetRef, isDisabled: !isOpen });
  const { updateFiles } = useCommit();
  const { textInfo, setTextInfo } = useEssential();
  const [publicationInfos, setPublicationInfos] = useState(
    textInfo.PublicationInfos
  );
  const [patentInfos, setPatentInfos] = useState(textInfo.patentInfos);
  const [editIndex, setEditIndex] = useState(null);
  const [activeTab, setActiveTab] = useState("publication");

  useEffect(() => {
    setPublicationInfos(
      [...textInfo.PublicationInfos].sort((a, b) => a.index - b.index)
    );
    setPatentInfos([...textInfo.patentInfos].sort((a, b) => a.index - b.index));
  }, [textInfo.PublicationInfos, textInfo.patentInfos]);

  const onSave = async () => {
    let textInfoTmp = JSON.parse(
      JSON.stringify({
        ...textInfo,
        PublicationInfos: publicationInfos,
        patentInfos: patentInfos,
      })
    );
    await updateFiles(
      [
        {
          action: "add",
          path: "datas/textInfos.json",
          content: JSON.stringify(textInfoTmp, null, 2),
        },
      ],
      "Update publication and patent infos"
    );
    alert("성공적으로 저장하였습니다. 적용에는 5분정도 소요됩니다.");
  };

  const handleInputChange = (index, field, value, type) => {
    if (type === "publication") {
      setPublicationInfos((prev) =>
        prev.map((publication, i) =>
          i === index ? { ...publication, [field]: value } : publication
        )
      );
    } else {
      setPatentInfos((prev) =>
        prev.map((patent, i) =>
          i === index ? { ...patent, [field]: value } : patent
        )
      );
    }
  };

  const moveItem = (index, direction, type) => {
    if (type === "publication") {
      setPublicationInfos((prev) => {
        const newItems = [...prev];
        const targetIndex = direction === "up" ? index - 1 : index + 1;
        if (targetIndex < 0 || targetIndex >= newItems.length) return prev;
        [newItems[index], newItems[targetIndex]] = [
          newItems[targetIndex],
          newItems[index],
        ];
        return newItems.map((item, i) => ({
          ...item,
          index: i + 1,
        }));
      });
    } else {
      setPatentInfos((prev) => {
        const newItems = [...prev];
        const targetIndex = direction === "up" ? index - 1 : index + 1;
        if (targetIndex < 0 || targetIndex >= newItems.length) return prev;
        [newItems[index], newItems[targetIndex]] = [
          newItems[targetIndex],
          newItems[index],
        ];
        return newItems.map((item, i) => ({
          ...item,
          index: i + 1,
        }));
      });
    }
  };

  const addNewItem = (type) => {
    if (type === "publication") {
      const newPublication = {
        index: publicationInfos.length + 1,
        title: "",
        authors: "",
        journal: "",
        paperLink: "",
        codeLink: "",
      };
      setPublicationInfos((prev) => [...prev, newPublication]);
      setEditIndex(publicationInfos.length);
    } else {
      const newPatent = {
        index: patentInfos.length + 1,
        title: "",
        inventors: "",
        patentNumber: "",
        patentLink: "",
      };
      setPatentInfos((prev) => [...prev, newPatent]);
      setEditIndex(patentInfos.length);
    }
  };

  const handleTabChange = (tab) => {
    if (editIndex !== null) {
      if (confirm("변경한 내용을 초기화하시겠습니까?")) {
        setEditIndex(null);
        setActiveTab(tab);
      }
    } else {
      setActiveTab(tab);
    }
  };

  const deleteItem = (index, type) => {
    if (type === "publication") {
      setPublicationInfos((prev) =>
        prev
          .filter((_, i) => i !== index)
          .map((item, i) => ({
            ...item,
            index: i + 1,
          }))
      );
    } else {
      setPatentInfos((prev) =>
        prev
          .filter((_, i) => i !== index)
          .map((item, i) => ({
            ...item,
            index: i + 1,
          }))
      );
    }
  };

  return (
    <>
      <Modal
        isDismissable={false}
        isKeyboardDismissDisabled={true}
        ref={targetRef}
        isOpen={isOpen}
        onOpenChange={onOpenChange}
        backdrop="transparent"
        hideCloseButton
        classNames={{
          body: "py-6 p-4 bg-neutral-100",
          base: "relative pointer-events-auto flex border-gray-300 bg-white text-gray-800 max-w-[600px] shadow-lg",
          header: "border-b-[1px] border-gray-300 p-2 ",
          footer: "border-t-[1px] border-gray-300 p-2",
          closeButton: "hover:bg-gray-100 active:bg-gray-200",
          wrapper: "pointer-events-none overflow-auto z-50",
        }}
      >
        <ModalContent>
          {(onClose) => (
            <>
              <ModalHeader {...moveProps} className="flex flex-col gap-1">
                <div className="flex justify-between">
                  <button
                    className={`px-4 py-2 ${
                      activeTab === "publication"
                        ? "bg-blue-500 text-white"
                        : "bg-gray-200"
                    }`}
                    onClick={() => handleTabChange("publication")}
                  >
                    Publications
                  </button>
                  <button
                    className={`px-4 py-2 ${
                      activeTab === "patent"
                        ? "bg-blue-500 text-white"
                        : "bg-gray-200"
                    }`}
                    onClick={() => handleTabChange("patent")}
                  >
                    Patents
                  </button>
                </div>
              </ModalHeader>
              <ModalBody>
                <div className="relative w-full max-h-[70vh] overflow-y-auto">
                  {activeTab === "publication" &&
                    publicationInfos.map((publication, index) => (
                      <div
                        key={index}
                        className="mb-4 rounded-md p-1 bg-white transition-all"
                      >
                        {editIndex === index ? (
                          <div className="flex flex-col gap-2">
                            <label className="block text-sm font-medium text-gray-700">
                              Title:
                            </label>
                            <input
                              className="bg-neutral-100 p-2 py-1 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                              value={publication.title}
                              onChange={(e) =>
                                handleInputChange(
                                  index,
                                  "title",
                                  e.target.value,
                                  "publication"
                                )
                              }
                            />
                            <label className="block text-sm font-medium text-gray-700">
                              Authors:
                            </label>
                            <input
                              className="bg-neutral-100 p-2 py-1 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                              value={publication.authors}
                              onChange={(e) =>
                                handleInputChange(
                                  index,
                                  "authors",
                                  e.target.value,
                                  "publication"
                                )
                              }
                            />
                            <label className="block text-sm font-medium text-gray-700">
                              Journal:
                            </label>
                            <input
                              className="bg-neutral-100 p-2 py-1 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                              value={publication.journal}
                              onChange={(e) =>
                                handleInputChange(
                                  index,
                                  "journal",
                                  e.target.value,
                                  "publication"
                                )
                              }
                            />
                            <label className="block text-sm font-medium text-gray-700">
                              Paper Link:
                            </label>
                            <input
                              className="bg-neutral-100 p-2 py-1 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                              value={publication.paperLink}
                              onChange={(e) =>
                                handleInputChange(
                                  index,
                                  "paperLink",
                                  e.target.value,
                                  "publication"
                                )
                              }
                            />
                            <label className="block text-sm font-medium text-gray-700">
                              Code Link:
                            </label>
                            <input
                              className="bg-neutral-100 p-2 py-1 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                              value={publication.codeLink}
                              onChange={(e) =>
                                handleInputChange(
                                  index,
                                  "codeLink",
                                  e.target.value,
                                  "publication"
                                )
                              }
                            />
                            <Button
                              color="primary"
                              className="bg-blue-500 rounded-md p-2 text-white"
                              onPress={() => setEditIndex(null)}
                            >
                              Close
                            </Button>
                          </div>
                        ) : (
                          <div className="flex flex-col gap-2">
                            <h3 className="text-lg font-semibold">
                              {publication.title}
                            </h3>
                            <h3 className="text-md font-normal">
                              {publication.journal}
                            </h3>
                            <div className="flex gap-2">
                              <Button
                                className="bg-blue-500 rounded-md w-full p-2 text-white"
                                color="primary"
                                onPress={() => setEditIndex(index)}
                              >
                                Edit
                              </Button>
                              <Button
                                color="danger"
                                className="bg-red-500 rounded-md p-2 px-4 text-white"
                                onPress={() =>
                                  confirm("정말로 삭제하겠습니까?") &&
                                  deleteItem(index, "publication")
                                }
                              >
                                Delete
                              </Button>
                              <Button
                                className="p-2 px-4 rounded-md border border-gray-500 text-gray-800"
                                color="secondary"
                                onPress={() =>
                                  moveItem(index, "up", "publication")
                                }
                              >
                                UP
                              </Button>
                              <Button
                                className="p-2 px-4 rounded-md border border-gray-500 text-gray-800"
                                color="secondary"
                                onPress={() =>
                                  moveItem(index, "down", "publication")
                                }
                              >
                                DOWN
                              </Button>
                            </div>
                          </div>
                        )}
                      </div>
                    ))}
                  {activeTab === "patent" &&
                    patentInfos.map((patent, index) => (
                      <div
                        key={index}
                        className="mb-4 rounded-md p-1 bg-white transition-all"
                      >
                        {editIndex === index ? (
                          <div className="flex flex-col gap-2">
                            <label className="block text-sm font-medium text-gray-700">
                              Title:
                            </label>
                            <input
                              className="bg-neutral-100 p-2 py-1 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                              value={patent.title}
                              onChange={(e) =>
                                handleInputChange(
                                  index,
                                  "title",
                                  e.target.value,
                                  "patent"
                                )
                              }
                            />
                            <label className="block text-sm font-medium text-gray-700">
                              Inventors:
                            </label>
                            <input
                              className="bg-neutral-100 p-2 py-1 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                              value={patent.inventors}
                              onChange={(e) =>
                                handleInputChange(
                                  index,
                                  "inventors",
                                  e.target.value,
                                  "patent"
                                )
                              }
                            />
                            <label className="block text-sm font-medium text-gray-700">
                              Patent Number:
                            </label>
                            <input
                              className="bg-neutral-100 p-2 py-1 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                              value={patent.patentNumber}
                              onChange={(e) =>
                                handleInputChange(
                                  index,
                                  "patentNumber",
                                  e.target.value,
                                  "patent"
                                )
                              }
                            />
                            <label className="block text-sm font-medium text-gray-700">
                              Patent Link:
                            </label>
                            <input
                              className="bg-neutral-100 p-2 py-1 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                              value={patent.patentLink}
                              onChange={(e) =>
                                handleInputChange(
                                  index,
                                  "patentLink",
                                  e.target.value,
                                  "patent"
                                )
                              }
                            />
                            <Button
                              color="primary"
                              className="bg-blue-500 rounded-md p-2 text-white"
                              onPress={() => setEditIndex(null)}
                            >
                              Close
                            </Button>
                          </div>
                        ) : (
                          <div className="flex flex-col gap-2">
                            <h3 className="text-lg font-semibold">
                              {patent.title}
                            </h3>
                            <h3 className="text-md font-normal">
                              {patent.patentNumber}
                            </h3>
                            <div className="flex gap-2">
                              <Button
                                className="bg-blue-500 rounded-md w-full p-2 text-white"
                                color="primary"
                                onPress={() => setEditIndex(index)}
                              >
                                Edit
                              </Button>
                              <Button
                                color="danger"
                                className="bg-red-500 rounded-md p-2 px-4 text-white"
                                onPress={() =>
                                  confirm("정말로 삭제하겠습니까?") &&
                                  deleteItem(index, "patent")
                                }
                              >
                                Delete
                              </Button>
                              <Button
                                className="p-2 px-4 rounded-md border border-gray-500 text-gray-800"
                                color="secondary"
                                onPress={() => moveItem(index, "up", "patent")}
                              >
                                UP
                              </Button>
                              <Button
                                className="p-2 px-4 rounded-md border border-gray-500 text-gray-800"
                                color="secondary"
                                onPress={() =>
                                  moveItem(index, "down", "patent")
                                }
                              >
                                DOWN
                              </Button>
                            </div>
                          </div>
                        )}
                      </div>
                    ))}
                </div>
              </ModalBody>
              <ModalFooter>
                <Button color="primary" onPress={onSave}>
                  Save All
                </Button>
                <Button color="primary" onPress={() => addNewItem(activeTab)}>
                  Add New
                </Button>
                <Button color="danger" variant="light" onPress={onClose}>
                  Close
                </Button>
              </ModalFooter>
            </>
          )}
        </ModalContent>
      </Modal>
    </>
  );
}
