import { useState } from "react";
import useEssential from "./useEssential";

const useCommit = () => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [commitResponse, setCommitResponse] = useState(null);
  const { admin } = useEssential();

  const owner = "BearAILab";
  const repo = "BEARAILab.github.io";

  const getLatestCommitSha = async () => {
    try {
      setLoading(true);
      const response = await fetch(
        `https://api.github.com/repos/${owner}/${repo}/git/refs/heads/main`,
        {
          headers: { Authorization: `token ${admin.token}` },
        }
      );

      if (!response.ok) {
        throw new Error("Failed to fetch latest commit SHA");
      }

      const data = await response.json();
      return data.object.sha;
    } catch (err) {
      setError(err.message);
      return null;
    } finally {
      setLoading(false);
    }
  };

  const createBlob = async (fileContent, filePath) => {
    try {
      const isImage = /\.(png|jpg|jpeg)$/i.test(filePath);
      const encoding = isImage ? "base64" : "utf-8";

      const response = await fetch(
        `https://api.github.com/repos/${owner}/${repo}/git/blobs`,
        {
          method: "POST",
          headers: {
            Authorization: `token ${admin.token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            content: fileContent,
            encoding: encoding,
          }),
        }
      );

      if (!response.ok) {
        throw new Error("Failed to create blob");
      }

      const result = await response.json();
      return result.sha;
    } catch (err) {
      setError(err.message);
      return null;
    }
  };

  const getFileSha = async (filePath) => {
    try {
      const response = await fetch(
        `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}`,
        {
          headers: { Authorization: `token ${admin.token}` },
        }
      );

      if (response.status === 404) {
        return null;
      }

      if (!response.ok) {
        throw new Error(`Failed to fetch file: ${filePath}`);
      }

      const fileData = await response.json();
      return fileData.sha;
    } catch (err) {
      setError(err.message);
      return null;
    }
  };

  const createTree = async (files, baseTreeSha) => {
    try {
      const treeItems = await Promise.all(
        files.map(async ({ action, path, content }) => {
          if (action === "delete") {
            return { path, mode: "100644", type: "blob", sha: null };
          }

          const blobSha = await createBlob(content, path);
          return { path, mode: "100644", type: "blob", sha: blobSha };
        })
      );

      const response = await fetch(
        `https://api.github.com/repos/${owner}/${repo}/git/trees`,
        {
          method: "POST",
          headers: {
            Authorization: `token ${admin.token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            base_tree: baseTreeSha,
            tree: treeItems,
          }),
        }
      );

      if (!response.ok) {
        throw new Error("Failed to create tree");
      }

      const result = await response.json();
      return result.sha;
    } catch (err) {
      setError(err.message);
      return null;
    }
  };

  const createCommit = async (treeSha, parentCommitSha, message) => {
    try {
      const response = await fetch(
        `https://api.github.com/repos/${owner}/${repo}/git/commits`,
        {
          method: "POST",
          headers: {
            Authorization: `token ${admin.token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            message: `[${admin.user}] ${message}`,
            tree: treeSha,
            parents: [parentCommitSha],
          }),
        }
      );

      if (!response.ok) {
        throw new Error("Failed to create commit");
      }

      const result = await response.json();
      return result.sha;
    } catch (err) {
      setError(err.message);
      return null;
    }
  };

  const updateBranch = async (commitSha) => {
    try {
      const response = await fetch(
        `https://api.github.com/repos/${owner}/${repo}/git/refs/heads/main`,
        {
          method: "PATCH",
          headers: {
            Authorization: `token ${admin.token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ sha: commitSha }),
        }
      );

      if (!response.ok) {
        throw new Error("Failed to update branch reference");
      }
    } catch (err) {
      setError(err.message);
    }
  };

  const updateFiles = async (files, message) => {
    try {
      setLoading(true);

      const latestCommitSha = await getLatestCommitSha();
      if (!latestCommitSha) return;

      const commitResponse = await fetch(
        `https://api.github.com/repos/${owner}/${repo}/git/commits/${latestCommitSha}`,
        {
          headers: { Authorization: `token ${admin.token}` },
        }
      );

      if (!commitResponse.ok) {
        throw new Error("Failed to fetch latest commit details");
      }

      const commitData = await commitResponse.json();
      const baseTreeSha = commitData.tree.sha;

      // 기존 파일의 SHA를 가져옴 (삭제를 위해 필요)
      const updatedFiles = await Promise.all(
        files.map(async (file) => {
          if (file.action === "delete") {
            const fileSha = await getFileSha(file.path);
            if (!fileSha) {
              console.warn(`File not found: ${file.path}`);
              return null;
            }
          }
          return file;
        })
      );

      const validFiles = updatedFiles.filter(Boolean);

      if (validFiles.length === 0) {
        setLoading(false);
        return;
      }

      const newTreeSha = await createTree(validFiles, baseTreeSha);
      if (!newTreeSha) return;

      const newCommitSha = await createCommit(
        newTreeSha,
        latestCommitSha,
        message
      );
      if (!newCommitSha) return;

      await updateBranch(newCommitSha);

      setCommitResponse({ sha: newCommitSha });
      return newCommitSha;
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return { loading, error, commitResponse, updateFiles };
};

export default useCommit;
