import React from "react";
import PropTypes from "prop-types";
import { marked } from "marked";
import { IoMdArrowDroprightCircle } from "react-icons/io";

const CustomText = ({ markdown, className, fontSize, id, lineHeight }) => {
  const getMarkdownText = () => {
    let rawMarkup = marked(markdown);
    rawMarkup = rawMarkup.replace(
      /<h1>/g,
      `<h1 class="text-2xl mt-2 font-bold text-[#04589a] flex items-center">
      `
    );
    console.log(rawMarkup);
    return { __html: rawMarkup };
  };

  return (
    <div
      id={id}
      className={`${className} ${fontSize} ${lineHeight} `}
      dangerouslySetInnerHTML={getMarkdownText()}
    />
  );
};

CustomText.propTypes = {
  markdown: PropTypes.string.isRequired,
  className: PropTypes.string,
  fontSize: PropTypes.string,
  id: PropTypes.string,
  lineHeight: PropTypes.string,
};

CustomText.defaultProps = {
  className: "",
  fontSize: "text-base",
  id: null,
  lineHeight: "leading-normal",
};

export default CustomText;
