import React, { useEffect, useState } from "react";
import {
  Modal,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  useDraggable,
  Input,
} from "@heroui/react";
import useEssential from "../../hooks/useEssential";
import useCommit from "../../hooks/useCommit";
import MarkdownEditor from "../markdownEditor";
import { useDisclosure } from "@heroui/react";
import { set } from "@recoiljs/recoil";

export default function NoticeSettingMenu({ isOpen, onOpen, onOpenChange }) {
  const { admin } = useEssential();
  const targetRef = React.useRef(null);
  const { moveProps } = useDraggable({ targetRef, isDisabled: !isOpen });
  const { updateFiles } = useCommit();
  const { textInfo, setTextInfo } = useEssential();
  const [noticeInfos, setNoticeInfos] = useState(textInfo.noticeInfos);
  const [editIndex, setEditIndex] = useState(null);

  useEffect(() => {
    setNoticeInfos([...textInfo.noticeInfos].sort((a, b) => a.index - b.index));
  }, [textInfo.noticeInfos]);

  const onSave = async () => {
    let textInfoTmp = JSON.parse(
      JSON.stringify({
        ...textInfo,
        noticeInfos: noticeInfos,
      })
    );
    await updateFiles(
      [
        {
          action: "add",
          path: "datas/textInfos.json",
          content: JSON.stringify(textInfoTmp, null, 2),
        },
      ],
      "Update notice infos"
    );
    alert("성공적으로 저장하였습니다. 적용에는 5분정도 소요됩니다.");
  };

  const handleInputChange = (index, field, value) => {
    setNoticeInfos((prev) =>
      prev.map((notice, i) =>
        i === index ? { ...notice, [field]: value } : notice
      )
    );
  };

  const moveItem = (index, direction) => {
    setNoticeInfos((prev) => {
      const newItems = [...prev];
      const targetIndex = direction === "up" ? index - 1 : index + 1;
      if (targetIndex < 0 || targetIndex >= newItems.length) return prev;
      [newItems[index], newItems[targetIndex]] = [
        newItems[targetIndex],
        newItems[index],
      ];
      return newItems.map((item, i) => ({
        ...item,
        index: i + 1,
      }));
    });
  };

  const addNewItem = () => {
    const newNotice = {
      index: noticeInfos.length + 1,
      title: "",
      date: "",
      description: "",
      text: "",
    };
    setNoticeInfos((prev) => [...prev, newNotice]);
    setEditIndex(noticeInfos.length);
  };

  const deleteItem = (index) => {
    setNoticeInfos((prev) =>
      prev
        .filter((_, i) => i !== index)
        .map((item, i) => ({
          ...item,
          index: i + 1,
        }))
    );
  };

  const {
    isOpen: isEditorOpen,
    onOpen: onEditorOpen,
    onOpenChange: onEditorOpenChange,
  } = useDisclosure();

  return (
    <>
      <MarkdownEditor
        initialMarkdown={noticeInfos[editIndex]?.text}
        applyMarkdown={(markdown) => {
          handleInputChange(editIndex, "text", markdown);
        }}
        isOpen={isEditorOpen}
        onOpenChange={onEditorOpenChange}
      />

      <Modal
        isDismissable={false}
        isKeyboardDismissDisabled={true}
        ref={targetRef}
        isOpen={isOpen}
        onOpenChange={onOpenChange}
        backdrop="transparent"
        hideCloseButton
        classNames={{
          body: "py-6 p-4 bg-neutral-100",
          base: "relative pointer-events-auto flex border-gray-300 bg-white text-gray-800 max-w-[600px] shadow-lg",
          header: "border-b-[1px] border-gray-300 p-2 ",
          footer: "border-t-[1px] border-gray-300 p-2",
          closeButton: "hover:bg-gray-100 active:bg-gray-200",
          wrapper: "pointer-events-none overflow-auto z-50",
        }}
      >
        <ModalContent>
          {(onClose) => (
            <>
              <ModalHeader {...moveProps} className="flex flex-col gap-1">
                <div className="flex justify-between">
                  <h2 className="text-lg font-semibold">Notices</h2>
                </div>
              </ModalHeader>
              <ModalBody>
                <div className="relative w-full max-h-[70vh] overflow-y-auto">
                  {noticeInfos.map((notice, index) => (
                    <div
                      key={index}
                      className="mb-4 rounded-md p-1 bg-white transition-all"
                    >
                      {editIndex === index ? (
                        <div className="flex flex-col gap-2">
                          <label className="block text-sm font-medium text-gray-700">
                            Title:
                          </label>
                          <input
                            className="bg-neutral-100 p-2 py-1 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                            value={notice.title}
                            onChange={(e) =>
                              handleInputChange(index, "title", e.target.value)
                            }
                          />
                          <label className="block text-sm font-medium text-gray-700">
                            Date:
                          </label>
                          <input
                            className="bg-neutral-100 p-2 py-1 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                            value={notice.date}
                            onChange={(e) =>
                              handleInputChange(index, "date", e.target.value)
                            }
                          />
                          <label className="block text-sm font-medium text-gray-700">
                            Description:
                          </label>
                          <input
                            className="bg-neutral-100 p-2 py-1 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                            value={notice.description}
                            onChange={(e) =>
                              handleInputChange(
                                index,
                                "description",
                                e.target.value
                              )
                            }
                          />
                          <label className="block text-sm font-medium text-gray-700">
                            Text:
                          </label>
                          <Button
                            color="primary"
                            className="bg-blue-500 rounded-md p-2 text-white"
                            onPress={() => {
                              onEditorOpen();
                            }}
                          >
                            텍스트 편집
                          </Button>
                          <Button
                            color="primary"
                            className="bg-blue-500 rounded-md p-2 text-white"
                            onPress={() => setEditIndex(null)}
                          >
                            Close
                          </Button>
                        </div>
                      ) : (
                        <div className="flex flex-col gap-2">
                          <h3 className="text-lg font-semibold">
                            {notice.title}
                          </h3>
                          <h3 className="text-md font-normal">{notice.date}</h3>
                          <div className="flex gap-2">
                            <Button
                              className="bg-blue-500 rounded-md w-full p-2 text-white"
                              color="primary"
                              onPress={() => setEditIndex(index)}
                            >
                              Edit
                            </Button>
                            <Button
                              color="danger"
                              className="bg-red-500 rounded-md p-2 px-4 text-white"
                              onPress={() =>
                                confirm("정말로 삭제하겠습니까?") &&
                                deleteItem(index)
                              }
                            >
                              Delete
                            </Button>
                            <Button
                              className="p-2 px-4 rounded-md border border-gray-500 text-gray-800"
                              color="secondary"
                              onPress={() => moveItem(index, "up")}
                            >
                              UP
                            </Button>
                            <Button
                              className="p-2 px-4 rounded-md border border-gray-500 text-gray-800"
                              color="secondary"
                              onPress={() => moveItem(index, "down")}
                            >
                              DOWN
                            </Button>
                          </div>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </ModalBody>
              <ModalFooter>
                <Button color="primary" onPress={onSave}>
                  Save All
                </Button>
                <Button color="primary" onPress={addNewItem}>
                  Add New
                </Button>
                <Button color="danger" variant="light" onPress={onClose}>
                  Close
                </Button>
              </ModalFooter>
            </>
          )}
        </ModalContent>
      </Modal>
    </>
  );
}
