import React, { useState, useEffect } from "react";
import NoticeItem from "../componants/NoticeItem";
import { useParams } from "react-router-dom";
import { Divider, useDisclosure } from "@heroui/react";
import PageHero from "../componants/PageHero";
import useEssential from "../hooks/useEssential";
import { IoSettings } from "react-icons/io5";
import NoticeContent from "../componants/noticeContent";

const NoticeBoard = () => {
  const [notices, setNotices] = useState([]);

  const { links } = useEssential();

  const { textInfo } = useEssential();
  const { admin } = useEssential();

  const {
    onOpen: onNoticeContentOpen,
    onOpenChange: onNoticeContentOpenChange,
    isOpen: isNoticeContentOpen,
  } = useDisclosure();

  const [noticeItem, setNoticeItem] = useState(null);
  return (
    <>
      <NoticeContent
        isOpen={isNoticeContentOpen}
        onOpen={onNoticeContentOpen}
        onOpenChange={onNoticeContentOpenChange}
        noticeItem={noticeItem}
      />
      <div className="min-h-screen w-full h-full">
        <PageHero name="Notice Board"></PageHero>
        <section className="flex flex-col justify-center p-8 md:p-32 md:pt-8">
          <div className="flex flex-col w-full p-8 max-w-[70vw] mx-auto">
            <div className="flex flex-col mt-6">
              <Divider className="w-44 h-1 border-4 border-gray-800 mb-4" />
              {textInfo.noticeInfos.map((notice, index) => (
                <NoticeItem
                  onClick={() => {
                    setNoticeItem(notice);
                    onNoticeContentOpen();
                  }}
                  key={index}
                  {...notice}
                />
              ))}
            </div>
          </div>
        </section>
      </div>
    </>
  );
};

export default NoticeBoard;
