import React, { useState, useEffect } from "react";
import PageHero from "../componants/PageHero";
import PeopleSection from "../componants/ResearchersSection";
import useEssential from "../hooks/useEssential";
import { IoSettings } from "react-icons/io5";

const People = () => {
  const [profiles, setProfiles] = useState([]);
  const [activeTab, setActiveTab] = useState("researcher");
  const { links } = useEssential();
  const { admin } = useEssential();

  const { textInfo } = useEssential();

  return (
    <>
      <div className="min-h-screen w-full h-full">
        <PageHero
          name="People"
          activeTab={activeTab}
          setActiveTab={setActiveTab}
          navigations={links.peopleUrl.navigations}
        />
        <div
          className={`${admin.token ? "" : "hidden"} absolute p-2 right-16 top-96 bg-gradient-to-tr from-blue-500 to-green-500 rounded-lg`}
        >
          <IoSettings size={"40px"} color="white" />
        </div>
        {textInfo.peopleInfos.length === 0 ? (
          <div>Loading...</div>
        ) : (
          <>
            {activeTab === "alumni" ? (
              <PeopleSection
                type="Alumni"
                member={textInfo.peopleInfos.alumni || []}
              />
            ) : (
              <>
                <PeopleSection
                  type="Professor"
                  member={textInfo.peopleInfos.currentMember.professor || []}
                />
                <PeopleSection
                  type="Member"
                  member={textInfo.peopleInfos.currentMember.member || []}
                />
                <PeopleSection
                  type="Student"
                  member={textInfo.peopleInfos.currentMember.student || []}
                />
              </>
            )}
          </>
        )}
      </div>
    </>
  );
};

export default People;
